/* Generated from jmggaravito-sudo/terminal-sync@3c7d784fdb2432dc14cdcd475da41680ff02035d; do not edit by hand. */
export const LANDING_USE_CASES = {"source":{"application":{"repository":"jmggaravito-sudo/terminal-sync","ref":"3c7d784fdb2432dc14cdcd475da41680ff02035d","commit":"3c7d784fdb2432dc14cdcd475da41680ff02035d","dataFile":"src/data/useCases.ts"}},"categories":[{"id":"sales","es":"Conseguir más clientes","en":"Get more customers"},{"id":"marketing","es":"Marketing","en":"Marketing"},{"id":"support","es":"Atención al cliente","en":"Customer support"},{"id":"operations","es":"Operaciones","en":"Operations"},{"id":"hr","es":"Recursos Humanos","en":"Human Resources"},{"id":"finance","es":"Finanzas","en":"Finance"},{"id":"legal","es":"Legal","en":"Legal"},{"id":"ecommerce","es":"Correo electrónico","en":"Email"},{"id":"dev","es":"Programas","en":"Programs"},{"id":"strategy","es":"Dirección y estrategia","en":"Leadership and strategy"},{"id":"market","es":"Mercado y competencia","en":"Market & competitors"},{"id":"social","es":"Redes y contenido","en":"Social media & content"},{"id":"travel","es":"Turismo y alojamiento","en":"Travel & lodging"},{"id":"continuity","es":"Continuidad","en":"Continuity"}],"cases":[{"id":"sales-001","area":"sales","es":{"t":"Crear propuesta comercial","d":"Genera una propuesta profesional lista para enviar a un cliente.","p":"Ayúdame a crear una propuesta comercial para mi empresa.\n\nMi empresa vende: [describir tu producto o servicio].\nMi cliente ideal es: [tipo de cliente].\nEl objetivo de la propuesta es: [cerrar venta / agendar reunión / firmar contrato].\n\nIncluye: resumen ejecutivo, propuesta de valor, alcance del servicio, beneficios, precio sugerido, condiciones y próximos pasos."},"en":{"t":"Create a sales proposal","d":"Generates a professional proposal ready to send to a client.","p":"Help me create a sales proposal for my company.\n\nMy company sells: [describe your product or service].\nMy ideal client is: [type of client].\nThe goal of the proposal is: [close sale / schedule meeting / sign contract].\n\nInclude: executive summary, value proposition, scope of service, benefits, suggested price, terms and next steps."}},{"id":"sales-002","area":"sales","es":{"t":"Preparar una reunión de ventas","d":"Te llega un guion con preguntas clave y objeciones esperadas.","p":"Voy a tener una reunión de ventas con un cliente potencial. Ayúdame a prepararla.\n\nEl cliente: [nombre de la empresa y a qué se dedica].\nLo que les voy a ofrecer: [producto/servicio].\nMi objetivo en la reunión: [cerrar / avanzar al siguiente paso / entender necesidad].\n\nDame: un guion para abrir la reunión, las 5 preguntas más importantes que debo hacer, las 3 objeciones más probables y cómo responderlas, y un cierre claro."},"en":{"t":"Prepare for a sales meeting","d":"You receive a script with key questions and expected objections.","p":"I'm going to have a sales meeting with a potential client. Help me prepare it.\n\nThe client: [company name and what it does].\nWhat I'll offer them: [product/service].\nMy objective in the meeting: [close / move to the next step / understand needs].\n\nGive me: a script to open the meeting, the 5 most important questions I should ask, the 3 most likely objections and how to respond to them, and a clear close."}},{"id":"sales-003","area":"sales","es":{"t":"Hacer seguimiento a prospectos","d":"Mensajes de seguimiento que reactivan conversaciones sin sonar insistente.","p":"Tengo prospectos que dejaron de responder. Ayúdame a escribir 3 mensajes de seguimiento profesionales y cálidos.\n\nContexto del prospecto: [qué hablamos antes y cuánto tiempo pasó].\nProducto/servicio: [describir].\nCanal: [email / WhatsApp / LinkedIn].\n\nUn mensaje corto que reactive la conversación sin sonar insistente, uno que aporte valor (recurso, artículo, dato) y uno final de cierre amable."},"en":{"t":"Follow up with prospects","d":"Follow-up messages that reactivate conversations without sounding pushy.","p":"I have prospects who stopped responding. Help me write 3 professional, warm follow-up messages.\n\nProspect context: [what we talked about before and how much time passed].\nProduct/service: [describe].\nChannel: [email / WhatsApp / LinkedIn].\n\nOne short message to reactivate the conversation without sounding pushy, one that adds value (resource, article, statistic) and one final polite closing message."}},{"id":"sales-004","area":"sales","es":{"t":"Crear guion de llamada en frío","d":"Guion claro de 60 segundos para abrir conversaciones nuevas.","p":"Necesito un guion de llamada en frío que no suene a vendedor agresivo.\n\nMi empresa: [describir].\nA quién llamo: [perfil del decisor].\nQué les ofrezco: [beneficio principal en una frase].\n\nDame: apertura de 15 segundos, propuesta de valor en una frase, una pregunta abierta para descubrir necesidad, manejo de las 3 objeciones más comunes y un cierre claro pidiendo agendar."},"en":{"t":"Create a cold call script","d":"Clear 60-second script to start new conversations.","p":"I need a cold call script that doesn't sound like an aggressive salesperson.\n\nMy company: [describe].\nWho I'm calling: [decision-maker profile].\nWhat I offer them: [main benefit in one sentence].\n\nGive me: a 15-second opening, a one-sentence value proposition, an open question to uncover needs, handling for the 3 most common objections, and a clear close asking to schedule."}},{"id":"sales-005","area":"sales","es":{"t":"Escribir email de venta en frío","d":"Email corto que abre conversaciones sin parecer spam.","p":"Ayúdame a escribir un email de venta en frío que el destinatario realmente lea.\n\nMi empresa: [describir].\nA quién le escribo: [perfil].\nQué problema resuelve mi producto: [describir].\n\nQuiero: un asunto que invite a abrir, un saludo personalizado, una frase que conecte con su realidad, una oferta concreta y una pregunta simple para que respondan. Máximo 100 palabras."},"en":{"t":"Write a cold sales email","d":"Short email that opens conversations without sounding like spam.","p":"Help me write a cold sales email that the recipient will actually read.\n\nMy company: [describe].\nWho I'm writing to: [profile].\nWhat problem my product solves: [describe].\n\nI want: a subject that invites opening, a personalized greeting, a sentence that connects with their reality, a concrete offer and a simple question for them to answer. Maximum 100 words."}},{"id":"sales-006","area":"sales","es":{"t":"Analizar por qué perdí una venta","d":"Diagnóstico claro y acciones concretas para no perder ventas similares.","p":"Acabo de perder una venta importante y quiero entender por qué.\n\nContexto: [describir el cliente, el producto y por qué crees que se cayó].\nLo que dijo el cliente: [palabras exactas si las recuerdas].\n\nAyúdame a identificar las 3 causas más probables, las preguntas que debí hacer antes y un plan concreto para no repetir el error con clientes similares."},"en":{"t":"Analyze why I lost a sale","d":"Clear diagnosis and concrete actions to avoid losing similar sales.","p":"I just lost an important sale and I want to understand why.\n\nContext: [describe the client, the product, and why you think it fell through].\nWhat the client said: [exact words if you remember them].\n\nHelp me identify the 3 most likely causes, the questions I should have asked earlier, and a concrete plan to avoid repeating the mistake with similar clients."}},{"id":"sales-007","area":"sales","es":{"t":"Crear pitch deck de ventas","d":"Estructura clara y persuasiva para presentar tu empresa.","p":"Ayúdame a estructurar un pitch deck de ventas para mi empresa.\n\nMi negocio: [describir].\nA quién se lo voy a mostrar: [tipo de cliente].\nLo que quiero lograr: [cerrar venta / agendar demo / etc].\n\nDame la estructura ideal slide por slide (máximo 10 slides), con qué debe ir en cada uno y consejos de cómo presentarlo en vivo."},"en":{"t":"Create a sales pitch deck","d":"Clear, persuasive structure to present your company.","p":"Help me structure a sales pitch deck for my company.\n\nMy business: [describe].\nWho I'll show it to: [type of client].\nWhat I want to achieve: [close sale / schedule demo / etc].\n\nGive me the ideal slide-by-slide structure (maximum 10 slides), what should be on each one and tips on how to present it live."}},{"id":"sales-008","area":"sales","es":{"t":"Calificar leads entrantes","d":"Sistema simple para identificar los prospectos con más probabilidad de comprar.","p":"Quiero un sistema simple para calificar leads que me llegan.\n\nMi negocio: [describir].\nClientes ideales: [perfil].\nVolumen de leads: [aproximado por mes].\n\nDame: 5 preguntas que deben responder al contactarme, criterios para clasificar como Frío/Tibio/Caliente y qué hacer con cada tipo de lead."},"en":{"t":"Qualify incoming leads","d":"Simple system to identify prospects with the highest likelihood to buy.","p":"I want a simple system to qualify leads that come to me.\n\nMy business: [describe].\nIdeal customers: [profile].\nLead volume: [approximate per month].\n\nGive me: 5 questions they should answer when contacting me, criteria to classify as Cold/Warm/Hot and what to do with each type of lead."}},{"id":"sales-009","area":"sales","es":{"t":"Responder objeción de precio","d":"Respuestas listas para cuando un cliente dice 'está caro'.","p":"Mis clientes me dicen seguido que mi precio es alto. Quiero defenderlo sin bajar el valor.\n\nMi producto/servicio: [describir].\nMi precio: [valor].\nLa competencia cobra: [aproximado].\n\nDame 3 respuestas profesionales y empáticas para diferentes momentos del proceso de venta, y argumentos concretos para sostener el precio."},"en":{"t":"Respond to price objection","d":"Ready responses for when a customer says 'it's expensive'.","p":"My customers often tell me my price is high. I want to defend it without lowering value.\n\nMy product/service: [describe].\nMy price: [price].\nThe competition charges: [approximate].\n\nGive me 3 professional and empathetic responses for different moments in the sales process, and concrete arguments to support the price."}},{"id":"sales-010","area":"sales","es":{"t":"Crear secuencia de nurturing","d":"Plan de 5 mensajes para mantener calientes a los prospectos.","p":"Tengo prospectos que aún no compran pero están interesados. Quiero una secuencia de mensajes para mantenerlos cerca.\n\nMi producto/servicio: [describir].\nDuración del ciclo de venta típico: [días/semanas].\nCanal preferido: [email/WhatsApp].\n\nDame una secuencia de 5 mensajes para enviar durante 30 días: 1 que aporte valor, 1 caso de éxito, 1 que despierte urgencia, 1 con oferta clara y 1 de cierre amable."},"en":{"t":"Create nurturing sequence","d":"5-message plan to keep prospects warm.","p":"I have prospects who haven't bought yet but are interested. I want a message sequence to keep them close.\n\nMy product/service: [describe].\nTypical sales cycle length: [days/weeks].\nPreferred channel: [email/WhatsApp].\n\nGive me a sequence of 5 messages to send over 30 days: 1 that provides value, 1 success story, 1 that creates urgency, 1 with a clear offer and 1 for a courteous close."}},{"id":"mkt-001","area":"marketing","es":{"t":"Crear campaña Meta Ads","d":"Campaña completa con copies, segmentación y estructura de anuncios.","p":"Necesito armar una campaña de anuncios en Facebook e Instagram.\n\nMi producto/servicio: [describir].\nMi cliente ideal: [edad, ubicación, intereses].\nMi objetivo: [generar leads / vender / dar a conocer].\nPresupuesto diario: [monto].\n\nDame: 3 ángulos de anuncio diferentes, copy para cada ángulo (headline + cuerpo + CTA), descripción de la imagen ideal, segmentación recomendada y métricas que debo seguir."},"en":{"t":"Create Meta Ads campaign","d":"Complete campaign with copies, targeting and ad structure.","p":"I need to set up an ad campaign on Facebook and Instagram.\n\nMy product/service: [describe].\nMy ideal customer: [age, location, interests].\nMy objective: [generate leads / sell / raise awareness].\nDaily budget: [amount].\n\nGive me: 3 different ad angles, copy for each angle (headline + body + CTA), description of the ideal image, recommended targeting and metrics I should track."}},{"id":"mkt-002","area":"marketing","es":{"t":"Escribir una landing page","d":"Estructura y texto completo para una landing que convierte.","p":"Necesito una landing page para [producto/servicio].\n\nObjetivo: [agendar reunión / vender / capturar lead].\nMi cliente ideal: [describir].\nMis 3 diferenciales: [listar].\n\nDame la estructura completa con: hero (titular + subtítulo + CTA), beneficios principales, prueba social, descripción de servicio, FAQ y CTA final. Texto listo para copiar y pegar."},"en":{"t":"Write a landing page","d":"Complete structure and text for a high-converting landing page.","p":"I need a landing page for [product/service].\n\nObjective: [schedule a meeting / sell / capture a lead].\nMy ideal customer: [describe].\nMy 3 differentiators: [list].\n\nGive me the complete structure with: hero (headline + subheadline + CTA), main benefits, social proof, service description, FAQ and final CTA. Text ready to copy and paste."}},{"id":"mkt-003","area":"marketing","es":{"t":"Crear contenido para redes sociales","d":"Plan de 10 posts listos para publicar la próxima quincena.","p":"Necesito ideas y textos para publicar en redes sociales.\n\nMi negocio: [describir].\nMis redes: [Instagram, Facebook, LinkedIn, TikTok…].\nTono de marca: [profesional / cercano / divertido].\n\nDame 10 ideas de posts con: título sugerido, texto completo listo para publicar, hashtags relevantes y descripción de la imagen ideal. Mezcla educativos, vendedores e inspiradores."},"en":{"t":"Create social media content","d":"Plan of 10 posts ready to publish over the next two weeks.","p":"I need ideas and text to post on social media.\n\nMy business: [describe].\nMy networks: [Instagram, Facebook, LinkedIn, TikTok...].\nBrand tone: [professional / approachable / fun].\n\nGive me 10 post ideas with: suggested title, full text ready to publish, relevant hashtags and description of the ideal image. Mix educational, sales and inspirational posts."}},{"id":"mkt-004","area":"marketing","es":{"t":"Plan de marketing trimestral","d":"Plan de 90 días con objetivos, canales, acciones y métricas.","p":"Ayúdame a armar un plan de marketing para los próximos 3 meses.\n\nMi negocio: [describir].\nObjetivo principal: [vender más / dar a conocer / lanzar producto].\nPresupuesto mensual de marketing: [monto].\nCanales actuales: [redes, email, ads, web…].\n\nDame: objetivos SMART para 3 meses, acciones por canal por mes, presupuesto sugerido por canal y las 5 métricas clave para medir éxito."},"en":{"t":"Quarterly marketing plan","d":"90-day plan with objectives, channels, actions and metrics.","p":"Help me build a marketing plan for the next 3 months.\n\nMy business: [describe].\nMain objective: [sell more / raise awareness / launch a product].\nMonthly marketing budget: [amount].\nCurrent channels: [social, email, ads, web...].\n\nGive me: SMART objectives for 3 months, actions by channel by month, suggested budget allocation by channel and the 5 key metrics to measure success."}},{"id":"mkt-005","area":"marketing","es":{"t":"Escribir email para newsletter","d":"Newsletter atractivo con asunto que invite a abrir.","p":"Necesito un email para mi base de clientes.\n\nMi negocio: [describir].\nQué quiero comunicar: [novedad / promo / consejo / caso].\nAcción deseada: [comprar / agendar / leer artículo].\n\nDame: 3 opciones de asunto que inviten a abrir, un email completo (saludo, cuerpo, CTA), y un PD opcional para reforzar la acción."},"en":{"t":"Write newsletter email","d":"Engaging newsletter with a subject line that invites opens.","p":"I need an email for my customer list.\n\nMy business: [describe].\nWhat I want to communicate: [news / promo / tip / case].\nDesired action: [buy / schedule / read article].\n\nGive me: 3 subject line options that invite opens, a full email (greeting, body, CTA), and an optional P.S. to reinforce the action."}},{"id":"mkt-006","area":"marketing","es":{"t":"Crear estrategia de marca","d":"Identidad de marca clara: misión, tono, posicionamiento.","p":"Necesito definir la identidad y estrategia de mi marca.\n\nMi negocio: [describir].\nPor qué empecé: [historia].\nMi cliente ideal: [perfil].\nMis competidores: [3 principales].\n\nDame: misión y visión claras, propuesta de valor única, posicionamiento contra competencia, valores de marca, tono de comunicación y 5 frases clave que pueda usar consistentemente."},"en":{"t":"Create brand strategy","d":"Clear brand identity: mission, tone, positioning.","p":"I need to define my brand identity and strategy.\n\nMy business: [describe].\nWhy I started: [story].\nMy ideal customer: [profile].\nMy competitors: [3 main].\n\nGive me: clear mission and vision, unique value proposition, positioning against competitors, brand values, tone of communication and 5 key phrases I can use consistently."}},{"id":"mkt-007","area":"marketing","es":{"t":"Analizar competencia","d":"Diagnóstico claro de competidores y oportunidades para diferenciarte.","p":"Quiero analizar a mi competencia y encontrar oportunidades.\n\nMi negocio: [describir].\nMis principales competidores: [listar nombres y webs].\nLo que quiero entender: [precios / posicionamiento / contenido / debilidades].\n\nDame: análisis comparativo en tabla, 3 oportunidades claras donde puedo diferenciarme y 3 amenazas que debo cuidar."},"en":{"t":"Analyze competitors","d":"Clear diagnosis of competitors and opportunities to differentiate yourself.","p":"I want to analyze my competitors and find opportunities.\n\nMy business: [describe].\nMy main competitors: [list names and websites].\nWhat I want to understand: [prices / positioning / content / weaknesses].\n\nGive me: comparative analysis in a table, 3 clear opportunities where I can differentiate, and 3 threats I should watch out for."}},{"id":"mkt-008","area":"marketing","es":{"t":"Crear guion para video corto","d":"Guion para Reels, TikTok o YouTube Shorts que enganchan en 3 segundos.","p":"Necesito un guion para un video corto vertical (Reel/TikTok/Short).\n\nMi negocio: [describir].\nTema del video: [describir].\nDuración: [15-60 seg].\nObjetivo: [educar / vender / entretener].\n\nDame: gancho de los primeros 3 segundos, desarrollo del mensaje, CTA al final, descripción visual de cada escena y sugerencias de audio o música."},"en":{"t":"Create script for short video","d":"Script for Reels, TikTok or YouTube Shorts that hook in 3 seconds.","p":"I need a script for a vertical short video (Reel/TikTok/Short).\n\nMy business: [describe].\nVideo topic: [describe].\nDuration: [15-60 sec].\nObjective: [educate / sell / entertain].\n\nGive me: hook for the first 3 seconds, development of the message, CTA at the end, visual description of each scene and audio or music suggestions."}},{"id":"mkt-009","area":"marketing","es":{"t":"Crear estrategia SEO","d":"Plan claro para aparecer en Google cuando tus clientes buscan.","p":"Quiero que mi web aparezca en Google cuando mis clientes buscan.\n\nMi negocio: [describir].\nMi ubicación geográfica: [ciudad/país].\nQué venden mis clientes que buscan: [productos/servicios].\n\nDame: 20 palabras clave estratégicas (mezcla locales y generales), estructura de páginas que debe tener mi web, ideas de 10 artículos de blog y acciones técnicas básicas que debo aplicar."},"en":{"t":"Create SEO strategy","d":"Clear plan to appear on Google when your customers search.","p":"I want my website to appear on Google when my customers search.\n\nMy business: [describe].\nMy geographic location: [city/country].\nWhat my customers search for: [products/services].\n\nGive me: 20 strategic keywords (mix of local and general), website page structure that my site should have, ideas for 10 blog posts and basic technical actions I should apply."}},{"id":"mkt-010","area":"marketing","es":{"t":"Lanzar producto nuevo","d":"Plan de lanzamiento de 30 días con todo lo que necesitas.","p":"Voy a lanzar un producto nuevo y quiero un plan de lanzamiento sólido.\n\nProducto: [describir].\nFecha objetivo: [cuándo].\nCanales disponibles: [redes / email / web / ads].\nPresupuesto: [monto].\n\nDame: cuenta regresiva semana a semana, contenido para cada semana, email de pre-lanzamiento, lanzamiento y post-lanzamiento, métricas a seguir y plan de contingencia si las ventas no llegan."},"en":{"t":"Launch a new product","d":"30-day launch plan with everything you need.","p":"I'm launching a new product and want a solid launch plan.\n\nProduct: [describe].\nTarget date: [when].\nAvailable channels: [social / email / website / ads].\nBudget: [amount].\n\nGive me: week-by-week countdown, content for each week, pre-launch, launch and post-launch emails, metrics to track and a contingency plan if sales don't arrive."}},{"id":"sup-001","area":"support","es":{"t":"Responder reclamo difícil","d":"Respuesta empática y profesional que calma al cliente y propone solución.","p":"Un cliente me escribió un reclamo y necesito responder profesionalmente.\n\nLo que dice el cliente: [pegar mensaje].\nContexto del problema: [explicar].\nLo que puedo ofrecer: [opciones de solución].\n\nDame una respuesta que: reconozca el problema, muestre empatía, ofrezca solución concreta y mantenga la relación. Tono profesional pero humano."},"en":{"t":"Respond to a difficult complaint","d":"Empathetic and professional response that calms the customer and proposes a solution.","p":"A customer wrote me a complaint and I need to respond professionally.\n\nWhat the customer says: [paste message].\nContext of the problem: [explain].\nWhat I can offer: [options for resolution].\n\nGive me a response that: acknowledges the problem, shows empathy, offers a concrete solution and maintains the relationship. Tone professional but human."}},{"id":"sup-002","area":"support","es":{"t":"Crear FAQ para tu negocio","d":"Lista de preguntas frecuentes con respuestas claras.","p":"Necesito crear una sección de Preguntas Frecuentes para mi negocio.\n\nMi negocio: [describir].\nMi producto/servicio: [describir].\nDudas que escucho seguido: [listar las que recuerdes].\n\nDame: 15 preguntas frecuentes ordenadas por categoría (compra, entrega, devolución, garantía, etc) con respuestas claras y cortas, listas para publicar en web o WhatsApp."},"en":{"t":"Create FAQ for your business","d":"List of frequently asked questions with clear answers.","p":"I need to create a Frequently Asked Questions section for my business.\n\nMy business: [describe].\nMy product/service: [describe].\nQuestions I often hear: [list the ones you remember].\n\nGive me: 15 frequently asked questions organized by category (purchase, delivery, returns, warranty, etc.) with clear and short answers, ready to publish on the web or WhatsApp."}},{"id":"sup-003","area":"support","es":{"t":"Plantillas para WhatsApp Business","d":"10 respuestas tipo listas para responder rápido y consistente.","p":"Necesito plantillas de respuesta rápida para WhatsApp Business.\n\nMi negocio: [describir].\nLas 10 situaciones más comunes son: [listar las que recuerdes, ej: precio, horarios, ubicación, agendar, devoluciones…].\n\nDame 10 plantillas completas con tono cálido pero profesional, cortas, con emojis sutiles y CTA claro al final de cada una."},"en":{"t":"Templates for WhatsApp Business","d":"10 ready-to-use response templates to reply quickly and consistently.","p":"I need quick response templates for WhatsApp Business.\n\nMy business: [describe].\nThe 10 most common situations are: [list the ones you remember, e.g.: price, hours, location, booking, returns…].\n\nGive me 10 complete templates with a warm but professional tone, short, with subtle emojis and a clear CTA at the end of each one."}},{"id":"sup-011","area":"support","es":{"t":"Atender clientes por WhatsApp Business","d":"Flujo claro para responder, priorizar y escalar conversaciones por WhatsApp.","p":"Quiero usar WhatsApp Business como canal principal de atención al cliente.\n\nMi negocio: [describir].\nQué tipo de mensajes recibo: [precios / horarios / soporte / reclamos / reservas / pedidos].\nQué horario atiendo: [horario].\nCuándo debe entrar una persona: [casos sensibles].\n\nDame: flujo de atención completo, tipos de mensajes más comunes, respuestas sugeridas, reglas de prioridad, cuándo escalar a humano y checklist para operar esto con consistencia."},"en":{"t":"Handle customers via WhatsApp Business","d":"Clear flow to respond, prioritize and escalate conversations via WhatsApp.","p":"I want to use WhatsApp Business as the main customer support channel.\n\nMy business: [describe].\nWhat types of messages I receive: [prices / hours / support / complaints / reservations / orders].\nWhat hours I operate: [hours].\nWhen a person should intervene: [sensitive cases].\n\nGive me: complete support flow, most common message types, suggested responses, priority rules, when to escalate to a human and a checklist to operate this consistently."}},{"id":"sup-012","area":"support","es":{"t":"Soporte postventa por WhatsApp","d":"Recorrido postventa que reduce fricción y mejora la experiencia del cliente.","p":"Quiero usar WhatsApp Business para soporte postventa.\n\nQué vendo: [producto/servicio].\nQué problemas aparecen después de vender: [listar].\nQué sí puedo resolver por chat: [describir].\nQué tiene que pasar a otra área: [describir].\n\nDame: flujo postventa, respuestas base, alertas para escalar a humano, mensajes de seguimiento y cómo medir si el soporte está funcionando bien."},"en":{"t":"Post-sale support via WhatsApp","d":"Post-sale journey that reduces friction and improves the customer experience.","p":"I want to use WhatsApp Business for post-sale support.\n\nWhat I sell: [product/service].\nProblems that appear after selling: [list].\nWhat I CAN resolve via chat: [describe].\nWhat needs to go to another department: [describe].\n\nGive me: post-sale flow, base replies, alerts to escalate to a human, follow-up messages, and how to measure if support is working well."}},{"id":"sup-004","area":"support","es":{"t":"Política de devoluciones","d":"Política clara que protege al negocio y al cliente.","p":"Necesito redactar mi política de devoluciones y cambios.\n\nMi negocio: [describir].\nMi producto: [describir].\nLo que estoy dispuesto a aceptar: [condiciones].\nLo que NO acepto: [listar].\n\nDame una política clara y profesional, fácil de entender por el cliente, que cubra: plazos, condiciones, qué cubre y qué no, proceso paso a paso y cómo iniciar el reclamo."},"en":{"t":"Return policy","d":"Clear policy that protects the business and the customer.","p":"I need to write my returns and exchanges policy.\n\nMy business: [describe].\nMy product: [describe].\nWhat I'm willing to accept: [conditions].\nWhat I DO NOT accept: [list].\n\nGive me a clear and professional policy, easy for the customer to understand, that covers: deadlines, conditions, what is covered and what is not, step-by-step process and how to start a claim."}},{"id":"sup-005","area":"support","es":{"t":"Encuesta de satisfacción","d":"Encuesta corta y bien diseñada para medir y mejorar.","p":"Quiero medir la satisfacción de mis clientes.\n\nMi negocio: [describir].\nQué quiero entender: [calidad del servicio / atención / producto / precio].\nCuándo se la voy a enviar: [post-compra / mensual / trimestral].\n\nDame: 7 preguntas balanceadas (5 numéricas y 2 abiertas), un email de presentación de la encuesta y qué hacer con cada tipo de respuesta."},"en":{"t":"Customer satisfaction survey","d":"Short, well-designed survey to measure and improve.","p":"I want to measure my customers' satisfaction.\n\nMy business: [describe].\nWhat I want to understand: [service quality / support / product / price].\nWhen I will send it: [post-purchase / monthly / quarterly].\n\nGive me: 7 balanced questions (5 numeric and 2 open), a survey introduction email and what to do with each type of response."}},{"id":"sup-006","area":"support","es":{"t":"Manual de atención al cliente","d":"Guía para que tu equipo atienda igual de bien que tú.","p":"Quiero entrenar a mi equipo en atención al cliente.\n\nMi negocio: [describir].\nValores de marca: [listar].\nLo que NO quiero que pase: [errores comunes].\n\nDame un manual con: los 5 principios de atención de mi marca, el tono correcto, frases obligatorias y prohibidas, escenarios típicos con respuesta ideal y proceso de escalación cuando algo se complica."},"en":{"t":"Customer service manual","d":"Guide so your team serves customers as well as you do.","p":"I want to train my team in customer service.\n\nMy business: [describe].\nBrand values: [list].\nWhat I DO NOT want to happen: [common mistakes].\n\nGive me a manual with: the 5 customer-service principles of my brand, the correct tone, required and forbidden phrases, typical scenarios with ideal responses and the escalation process when something gets complicated."}},{"id":"sup-007","area":"support","es":{"t":"Disculpas por error grave","d":"Mensaje de disculpa que recupera la confianza del cliente.","p":"Mi empresa cometió un error con un cliente y necesito pedir disculpas formalmente.\n\nQué pasó: [describir].\nImpacto al cliente: [describir].\nQué vamos a hacer para compensar: [opciones].\n\nDame un mensaje de disculpa sincero, profesional y que no minimice el error. Que reconozca, explique brevemente la causa sin excusarse, ofrezca compensación concreta y compromiso futuro."},"en":{"t":"Apology for a serious error","d":"Apology message that regains the customer's trust.","p":"My company made a mistake with a customer and I need to apologize formally.\n\nWhat happened: [describe].\nImpact on the customer: [describe].\nWhat we will do to compensate: [options].\n\nGive me a sincere, professional apology message that does not minimize the error. It should acknowledge, briefly explain the cause without making excuses, offer concrete compensation and a commitment for the future."}},{"id":"sup-008","area":"support","es":{"t":"Pedir testimonio a cliente feliz","d":"Mensaje que consigue testimonios reales sin sentirse forzado.","p":"Tengo clientes felices y quiero pedirles testimonio para mi web y redes.\n\nMi negocio: [describir].\nQué me gustaría que destaquen: [resultados / experiencia / atención].\n\nDame: un mensaje cálido para pedir el testimonio, 3 preguntas guía para facilitarles la respuesta, una versión para WhatsApp y otra para email, y una nota de agradecimiento."},"en":{"t":"Ask for a testimonial from a happy customer","d":"Message that gets real testimonials without sounding forced.","p":"I have happy customers and I want to ask them for a testimonial for my website and social media.\n\nMy business: [describe].\nWhat I'd like them to highlight: [results / experience / service].\n\nGive me: a warm message to request the testimonial, 3 guiding questions to make it easy for them to respond, a WhatsApp version and an email version, and a thank-you note."}},{"id":"sup-009","area":"support","es":{"t":"Recuperar cliente perdido","d":"Mensaje para clientes que dejaron de comprar e invitarlos de regreso.","p":"Tengo clientes que antes compraban seguido y dejaron de hacerlo. Quiero recuperarlos.\n\nMi negocio: [describir].\nTiempo aproximado sin comprar: [meses].\nQué hay de nuevo en mi negocio: [novedades, mejoras, productos].\n\nDame: un mensaje cálido que reabra la conversación sin sonar a venta agresiva, una oferta clara pero respetuosa y una pregunta que invite a responder."},"en":{"t":"Win back a lost customer","d":"Message for customers who stopped buying to invite them back.","p":"I have customers who used to buy regularly and stopped. I want to win them back.\n\nMy business: [describe].\nApproximate time since last purchase: [months].\nWhat's new in my business: [news, improvements, products].\n\nGive me: a warm message that reopens the conversation without sounding like aggressive selling, a clear but respectful offer and a question that invites a reply."}},{"id":"sup-010","area":"support","es":{"t":"Documentar procedimiento de soporte","d":"Proceso paso a paso para responder rápido y consistente.","p":"Quiero documentar cómo se debe manejar el soporte al cliente en mi empresa.\n\nMi negocio: [describir].\nTipos de consulta más comunes: [listar].\nTiempos de respuesta deseados: [horas].\n\nDame un procedimiento paso a paso: cómo recibir la consulta, cómo clasificarla por urgencia, qué responder en menos de X horas, cuándo escalar a otra persona y cómo cerrar el caso correctamente."},"en":{"t":"Document the support procedure","d":"Step-by-step process to respond quickly and consistently.","p":"I want to document how support should be handled in my company.\n\nMy business: [describe].\nMost common types of inquiries: [list].\nDesired response times: [hours].\n\nGive me a step-by-step procedure: how to receive the inquiry, how to classify it by urgency, what to reply in less than X hours, when to escalate to someone else and how to properly close the case."}},{"id":"ops-001","area":"operations","es":{"t":"Documentar un proceso","d":"Proceso paso a paso documentado para que cualquiera pueda ejecutarlo.","p":"Necesito documentar un proceso de mi empresa para que mi equipo lo siga sin tener que preguntarme cada vez.\n\nProceso a documentar: [describir].\nQuién lo va a ejecutar: [rol].\nResultado esperado: [qué debe quedar al final].\n\nDame el proceso paso a paso, claro y simple: objetivo, materiales/herramientas necesarias, pasos en orden, tiempo estimado de cada paso, controles de calidad y qué hacer si algo sale mal."},"en":{"t":"Document a process","d":"Step-by-step process documented so anyone can execute it.","p":"I need to document a process in my company so my team can follow it without having to ask me each time.\n\nProcess to document: [describe].\nWho will execute it: [role].\nExpected outcome: [what should remain at the end].\n\nGive me the step-by-step process, clear and simple: objective, necessary materials/tools, steps in order, estimated time for each step, quality controls and what to do if something goes wrong."}},{"id":"ops-002","area":"operations","es":{"t":"Crear SOP (procedimiento estándar)","d":"SOP profesional que cualquier nuevo empleado puede seguir.","p":"Necesito un SOP (Standard Operating Procedure) profesional para una tarea recurrente.\n\nTarea: [describir].\nÁrea responsable: [departamento].\nFrecuencia: [diaria / semanal / mensual].\n\nDame un SOP en formato profesional: propósito, alcance, responsables, materiales, pasos detallados con responsable de cada uno, indicadores de éxito y registro/evidencia que debe quedar archivada."},"en":{"t":"Create SOP (Standard Operating Procedure)","d":"Professional SOP that any new employee can follow.","p":"I need a professional SOP (Standard Operating Procedure) for a recurring task.\n\nTask: [describe].\nResponsible area: [department].\nFrequency: [daily / weekly / monthly].\n\nGive me an SOP in professional format: purpose, scope, responsible parties, materials, detailed steps with the person responsible for each, success indicators and records/evidence that must be archived."}},{"id":"ops-003","area":"operations","es":{"t":"Optimizar costos operativos","d":"Diagnóstico de gastos con recomendaciones para reducir sin afectar calidad.","p":"Quiero reducir costos operativos sin afectar la calidad del servicio.\n\nMi negocio: [describir].\nGastos mensuales principales: [listar con monto aproximado].\nIngresos mensuales aproximados: [monto].\n\nDame: análisis de qué gastos son críticos vs opcionales, 5 oportunidades concretas de ahorro priorizadas por impacto, riesgos de cada recorte y plan de implementación."},"en":{"t":"Optimize operating costs","d":"Expense diagnosis with recommendations to reduce costs without affecting quality.","p":"I want to reduce operating costs without affecting service quality.\n\nMy business: [describe].\nMain monthly expenses: [list with approximate amount].\nApproximate monthly revenue: [amount].\n\nGive me: analysis of which expenses are critical vs optional, 5 concrete cost-saving opportunities prioritized by impact, risks of each cut and an implementation plan."}},{"id":"ops-004","area":"operations","es":{"t":"Plan de mejora continua","d":"Plan trimestral para mejorar un área específica de la operación.","p":"Quiero implementar un plan de mejora continua en un área de mi empresa.\n\nÁrea a mejorar: [describir].\nProblemas actuales: [listar].\nMeta deseada: [resultado en 3 meses].\n\nDame: diagnóstico inicial, 5 acciones de mejora priorizadas, cronograma de 3 meses, responsables sugeridos y métricas para medir el progreso."},"en":{"t":"Continuous improvement plan","d":"Quarterly plan to improve a specific operational area.","p":"I want to implement a continuous improvement plan in an area of my company.\n\nArea to improve: [describe].\nCurrent problems: [list].\nDesired goal: [result in 3 months].\n\nGive me: initial diagnosis, 5 prioritized improvement actions, 3-month timeline, suggested responsible persons and metrics to measure progress."}},{"id":"ops-005","area":"operations","es":{"t":"Lista de chequeo (checklist)","d":"Checklist clara que asegura que nada se olvide.","p":"Necesito una lista de chequeo para asegurar que una tarea se haga bien siempre.\n\nTarea: [describir].\nQuién la ejecuta: [rol].\nFrecuencia: [diaria / semanal / mensual].\nProblema más común si no se hace bien: [describir].\n\nDame una checklist ordenada lógicamente, con casillas para tildar, en formato listo para imprimir o enviar por WhatsApp."},"en":{"t":"Checklist","d":"Clear checklist that ensures nothing is forgotten.","p":"I need a checklist to ensure a task is always done correctly.\n\nTask: [describe].\nWho executes it: [role].\nFrequency: [daily / weekly / monthly].\nMost common problem if not done well: [describe].\n\nGive me a logically ordered checklist, with boxes to tick, in a format ready to print or send via WhatsApp."}},{"id":"ops-006","area":"operations","es":{"t":"Manual de operaciones","d":"Manual maestro de cómo opera tu empresa.","p":"Quiero un manual de operaciones que documente cómo funciona mi empresa, para que pueda delegar y escalar.\n\nMi empresa: [describir].\nÁreas principales: [listar].\nProcesos críticos: [listar].\n\nDame: tabla de contenidos completa, estructura por área, lo que debe ir en cada sección y orden recomendado de creación (qué empezar primero)."},"en":{"t":"Operations manual","d":"Master manual of how your company operates.","p":"I want an operations manual that documents how my company works, so I can delegate and scale.\n\nMy company: [describe].\nMain areas: [list].\nCritical processes: [list].\n\nGive me: complete table of contents, structure by area, what should go in each section and recommended order of creation (what to start first)."}},{"id":"ops-007","area":"operations","es":{"t":"Mejorar tiempos de entrega","d":"Plan claro para entregar más rápido sin perder calidad.","p":"Mis tiempos de entrega son más lentos que la competencia y quiero mejorarlos.\n\nMi negocio: [describir].\nTiempo actual de entrega: [días/horas].\nTiempo objetivo: [días/horas].\nProceso actual: [describir paso a paso].\n\nDame: diagnóstico de cuellos de botella, 3 mejoras concretas priorizadas por impacto, riesgos a considerar y métricas para monitorear el progreso."},"en":{"t":"Improve delivery times","d":"Clear plan to deliver faster without losing quality.","p":"My delivery times are slower than the competition and I want to improve them.\n\nMy business: [describe].\nCurrent delivery time: [days/hours].\nTarget time: [days/hours].\nCurrent process: [describe step by step].\n\nGive me: diagnosis of bottlenecks, 3 concrete improvements prioritized by impact, risks to consider and metrics to monitor progress."}},{"id":"ops-008","area":"operations","es":{"t":"Evaluar a un proveedor","d":"Marco para elegir o renegociar con proveedores objetivamente.","p":"Necesito evaluar a un proveedor objetivamente, ya sea para elegirlo o renegociar condiciones.\n\nProveedor: [describir qué provee].\nTiempo de relación: [tiempo].\nProblemas o dudas actuales: [describir].\n\nDame: 7 criterios de evaluación con su peso relativo, una matriz de evaluación lista para usar, preguntas para la reunión de renegociación y plan B si no se llega a acuerdo."},"en":{"t":"Evaluate a supplier","d":"Framework to choose or renegotiate with suppliers objectively.","p":"I need to evaluate a supplier objectively, either to choose them or renegotiate terms.\n\nSupplier: [describe what they supply].\nLength of relationship: [time].\nCurrent problems or doubts: [describe].\n\nGive me: 7 evaluation criteria with their relative weight, an evaluation matrix ready to use, questions for the renegotiation meeting and a Plan B if no agreement is reached."}},{"id":"ops-009","area":"operations","es":{"t":"Plan de contingencia","d":"Qué hacer cuando algo crítico falla en la operación.","p":"Quiero un plan de contingencia para los problemas que más temo en mi operación.\n\nMi negocio: [describir].\nLos 3 problemas que más me preocupan: [listar, ej: se enferma el equipo clave, falla el sistema, falta de stock].\n\nDame para cada problema: nivel de impacto, primeras 24 horas de respuesta, plan de comunicación interno y externo, recuperación y prevención futura."},"en":{"t":"Contingency Plan","d":"What to do when something critical fails in operations.","p":"I want a contingency plan for the problems I fear most in my operation.\n\nMy business: [describe].\nThe 3 problems I worry about most: [list, e.g.: key team gets sick, system failure, stockout].\n\nGive me for each problem: level of impact, first 24 hours of response, internal and external communication plan, recovery and future prevention."}},{"id":"ops-010","area":"operations","es":{"t":"Auditoría interna simple","d":"Diagnóstico claro de qué funciona, qué no y dónde empezar a mejorar.","p":"Quiero hacer una auditoría interna de mi negocio para ver dónde estoy bien y dónde mejorar.\n\nMi negocio: [describir].\nÁreas a auditar: [ventas / operaciones / atención / finanzas / equipo].\n\nDame: 5 preguntas críticas por área, escala de evaluación (1-5), formato simple de reporte, las 3 áreas a priorizar después de la auditoría y plan de seguimiento."},"en":{"t":"Simple Internal Audit","d":"Clear diagnosis of what works, what doesn't, and where to start improving.","p":"I want to do an internal audit of my business to see where I'm doing well and where to improve.\n\nMy business: [describe].\nAreas to audit: [sales / operations / customer service / finance / team].\n\nGive me: 5 critical questions per area, evaluation scale (1-5), simple report format, the 3 areas to prioritize after the audit and a follow-up plan."}},{"id":"hr-001","area":"hr","es":{"t":"Escribir oferta de trabajo","d":"Oferta de trabajo que atrae a los candidatos correctos.","p":"Necesito publicar una oferta de trabajo que atraiga buenos candidatos.\n\nPuesto: [describir rol].\nMi empresa: [describir].\nQué busco en la persona: [habilidades duras y blandas].\nLo que ofrezco: [salario, beneficios, cultura].\n\nDame una oferta con: título atractivo del puesto, resumen de la empresa, responsabilidades concretas, requisitos imprescindibles vs deseables, qué ofrecemos y proceso de postulación."},"en":{"t":"Write Job Posting","d":"Job posting that attracts the right candidates.","p":"I need to post a job that attracts good candidates.\n\nPosition: [describe role].\nMy company: [describe].\nWhat I'm looking for in the person: [hard and soft skills].\nWhat I offer: [salary, benefits, culture].\n\nGive me a posting with: attractive job title, company summary, concrete responsibilities, must-have vs desirable requirements, what we offer and application process."}},{"id":"hr-002","area":"hr","es":{"t":"Guion de entrevista","d":"Entrevista estructurada que descubre al candidato real.","p":"Voy a entrevistar candidatos para un puesto y quiero hacer una entrevista profesional.\n\nPuesto: [describir].\nLo que más necesito en la persona: [habilidades clave].\nNivel: [junior / semi senior / senior].\n\nDame: una entrevista estructurada de 45 minutos, 10 preguntas conductuales (situaciones reales), 5 preguntas técnicas, qué buscar en cada respuesta y red flags que debería identificar."},"en":{"t":"Interview Script","d":"Structured interview that uncovers the real candidate.","p":"I'm going to interview candidates for a role and want to run a professional interview.\n\nPosition: [describe].\nWhat I need most in the person: [key skills].\nLevel: [junior / mid-level / senior].\n\nGive me: a structured 45-minute interview, 10 behavioral questions (real situations), 5 technical questions, what to look for in each answer and red flags I should identify."}},{"id":"hr-003","area":"hr","es":{"t":"Plan de inducción para nuevo empleado","d":"Primer mes planificado para que el nuevo empleado se integre rápido.","p":"Voy a recibir un empleado nuevo y quiero que tenga una buena inducción.\n\nPuesto: [describir].\nDuración de la inducción: [días/semanas].\nQuién lo va a acompañar: [mentor/jefe].\n\nDame: cronograma día a día de la primera semana, objetivos por semana del primer mes, personas que debe conocer, documentos a entregar y reuniones de seguimiento sugeridas."},"en":{"t":"New Employee Onboarding Plan","d":"First month planned so the new employee integrates quickly.","p":"I'm about to receive a new employee and want them to have a good onboarding.\n\nPosition: [describe].\nOnboarding duration: [days/weeks].\nWho will accompany them: [mentor/manager].\n\nGive me: day-by-day schedule for the first week, weekly objectives for the first month, people they should meet, documents to hand over and suggested follow-up meetings."}},{"id":"hr-004","area":"hr","es":{"t":"Evaluación de desempeño","d":"Evaluación justa que motiva y orienta al empleado.","p":"Necesito hacer una evaluación de desempeño justa y útil.\n\nEmpleado: [puesto].\nTiempo en la empresa: [meses/años].\nObjetivos del último periodo: [describir].\nResultados: [describir].\n\nDame: criterios de evaluación profesionales, formato de reunión de evaluación, cómo dar feedback positivo y de mejora, plan de desarrollo para próximo periodo y plantilla de acuerdo de objetivos."},"en":{"t":"Performance Evaluation","d":"Fair evaluation that motivates and guides the employee.","p":"I need to perform a fair and useful performance evaluation.\n\nEmployee: [position].\nTime at the company: [months/years].\nObjectives from the last period: [describe].\nResults: [describe].\n\nGive me: professional evaluation criteria, format for the evaluation meeting, how to give positive and improvement feedback, development plan for the next period and a template for agreed objectives."}},{"id":"hr-005","area":"hr","es":{"t":"Carta de despido respetuosa","d":"Conversación y carta que cierra una etapa con dignidad.","p":"Tengo que desvincular a un empleado y quiero hacerlo de la forma más respetuosa y profesional posible.\n\nMotivo: [reducción / desempeño / cierre área].\nTiempo del empleado: [tiempo].\nLo que voy a ofrecer: [indemnización / referencia / tiempo].\n\nDame: guion para la conversación cara a cara, carta de desvinculación formal, qué decir y qué NO decir, próximos pasos administrativos y cómo comunicarlo al resto del equipo."},"en":{"t":"Respectful Termination Letter","d":"Conversation and letter that close a chapter with dignity.","p":"I have to terminate an employee and want to do it as respectfully and professionally as possible.\n\nReason: [reduction / performance / area closure].\nEmployee tenure: [time].\nWhat I will offer: [severance / reference / time].\n\nGive me: script for the face-to-face conversation, formal termination letter, what to say and what NOT to say, next administrative steps and how to communicate it to the rest of the team."}},{"id":"hr-006","area":"hr","es":{"t":"Plan de incentivos para equipo","d":"Sistema de bonos justo y motivador.","p":"Quiero implementar un plan de incentivos para mi equipo que sea justo y motivador.\n\nTamaño del equipo: [#].\nRoles: [listar].\nObjetivos clave del negocio: [vender más / mejorar atención / reducir costos].\nPresupuesto disponible: [monto o porcentaje].\n\nDame: estructura del plan, métricas por rol, frecuencia de pago, ejemplos concretos de cálculo y comunicación clara al equipo."},"en":{"t":"Team Incentive Plan","d":"Fair and motivating bonus system.","p":"I want to implement an incentive plan for my team that is fair and motivating.\n\nTeam size: [#].\nRoles: [list].\nKey business objectives: [sell more / improve service / reduce costs].\nBudget available: [amount or percentage].\n\nGive me: plan structure, metrics per role, payment frequency, concrete calculation examples and clear communication to the team."}},{"id":"hr-007","area":"hr","es":{"t":"Manual de bienvenida","d":"Manual de cultura, valores y reglas que cualquier nuevo empleado entiende.","p":"Quiero crear un manual de bienvenida para que cada nuevo empleado entienda la cultura y reglas de mi empresa.\n\nMi empresa: [describir].\nValores: [listar].\nHistoria breve: [describir].\nLas reglas más importantes: [listar].\n\nDame un manual con: bienvenida personal, historia y propósito, valores con ejemplos reales, reglas claras de convivencia, beneficios y políticas operativas."},"en":{"t":"Welcome handbook","d":"Culture, values and rules handbook that any new employee understands.","p":"I want to create a welcome handbook so every new employee understands my company's culture and rules.\n\nMy company: [describe].\nValues: [list].\nBrief history: [describe].\nMost important rules: [list].\n\nGive me a handbook with: personal welcome, history and purpose, values with real examples, clear conduct rules, benefits and operational policies."}},{"id":"hr-008","area":"hr","es":{"t":"Reunión de feedback difícil","d":"Conversación constructiva que mejora sin lastimar.","p":"Necesito tener una conversación difícil con un empleado sobre su desempeño.\n\nEmpleado: [rol].\nProblema concreto: [describir].\nTiempo del problema: [cuánto hace].\nLo que ya intenté: [describir].\n\nDame: guion para la reunión paso a paso, frases concretas para abrir y cerrar, cómo escuchar antes de hablar, plan de mejora con plazos y consecuencias si no mejora."},"en":{"t":"Difficult feedback meeting","d":"A constructive conversation that improves performance without causing harm.","p":"I need to have a difficult conversation with an employee about their performance.\n\nEmployee: [role].\nSpecific problem: [describe].\nDuration of the problem: [how long].\nWhat I've already tried: [describe].\n\nGive me: step-by-step meeting script, concrete phrases to open and close, how to listen before speaking, improvement plan with deadlines and consequences if there is no improvement."}},{"id":"hr-009","area":"hr","es":{"t":"Encuesta de clima laboral","d":"Encuesta corta que detecta problemas antes que escalen.","p":"Quiero medir cómo se siente mi equipo trabajando en mi empresa.\n\nTamaño del equipo: [#].\nLo que más me importa medir: [satisfacción / liderazgo / carga laboral / clima].\n\nDame: 12 preguntas balanceadas (10 numéricas y 2 abiertas), mensaje de presentación que invite a responder con sinceridad, cómo analizar resultados y plan de acción según señales de alerta."},"en":{"t":"Employee engagement survey","d":"A short survey that detects issues before they escalate.","p":"I want to measure how my team feels working at my company.\n\nTeam size: [#].\nWhat I most want to measure: [satisfaction / leadership / workload / climate].\n\nGive me: 12 balanced questions (10 numeric and 2 open), an introduction message that invites honest responses, how to analyze results and an action plan based on warning signs."}},{"id":"hr-010","area":"hr","es":{"t":"Plan de carrera","d":"Camino claro de crecimiento para retener al talento.","p":"Quiero crear un plan de carrera claro para retener a mis empleados clave.\n\nMi empresa: [describir].\nPuestos clave: [listar].\nQué busco evitar: [renuncias por falta de crecimiento].\n\nDame: estructura de niveles por área, criterios para subir de nivel, sueldo orientativo por nivel, plan de capacitación por nivel y cómo comunicarlo al equipo."},"en":{"t":"Career plan","d":"Clear growth path to retain talent.","p":"I want to create a clear career plan to retain my key employees.\n\nMy company: [describe].\nKey positions: [list].\nWhat I'm trying to avoid: [resignations due to lack of growth].\n\nGive me: structure of levels by area, criteria for promotion, indicative salary by level, training plan by level and how to communicate it to the team."}},{"id":"fin-001","area":"finance","es":{"t":"Análisis de flujo de caja","d":"Diagnóstico claro de tu flujo de dinero con alertas tempranas.","p":"Quiero analizar mi flujo de caja para tomar mejores decisiones.\n\nMi negocio: [describir].\nIngresos mensuales aproximados: [monto].\nGastos fijos: [listar].\nGastos variables principales: [listar].\n\nDame: análisis de salud financiera actual, las 3 alertas tempranas que debo monitorear, recomendaciones para mejorar el flujo y proyección realista a 3 meses."},"en":{"t":"Cash flow analysis","d":"Clear diagnosis of your cash flow with early warnings.","p":"I want to analyze my cash flow to make better decisions.\n\nMy business: [describe].\nApproximate monthly revenue: [amount].\nFixed expenses: [list].\nMain variable expenses: [list].\n\nGive me: analysis of current financial health, the 3 early warnings I should monitor, recommendations to improve cash flow and a realistic 3-month projection."}},{"id":"fin-002","area":"finance","es":{"t":"Presupuesto anual","d":"Presupuesto realista que se puede cumplir y medir.","p":"Necesito armar el presupuesto anual de mi empresa.\n\nMi negocio: [describir].\nIngresos del año anterior: [monto].\nMetas para este año: [crecimiento esperado].\nInversiones planeadas: [listar].\n\nDame: presupuesto mes a mes con ingresos y egresos por categoría, supuestos clave, escenario conservador y agresivo, indicadores de seguimiento mensual y revisiones trimestrales sugeridas."},"en":{"t":"Annual budget","d":"A realistic budget that can be met and measured.","p":"I need to build my company's annual budget.\n\nMy business: [describe].\nLast year's revenue: [amount].\nGoals for this year: [expected growth].\nPlanned investments: [list].\n\nGive me: month-by-month budget with revenues and expenses by category, key assumptions, conservative and aggressive scenarios, monthly tracking indicators and suggested quarterly reviews."}},{"id":"fin-003","area":"finance","es":{"t":"Análisis de rentabilidad por producto","d":"Descubrir cuáles productos te hacen ganar y cuáles te hacen perder.","p":"Quiero saber cuáles de mis productos/servicios son los más rentables.\n\nMi negocio: [describir].\nMis productos/servicios: [listar con precio].\nCostos por producto: [listar si los conoces].\n\nDame: análisis comparativo en tabla, margen por producto, los 3 que más aportan al negocio, los 3 que debería revisar o discontinuar y recomendaciones de pricing."},"en":{"t":"Profitability analysis by product","d":"Discover which products make you money and which make you lose it.","p":"I want to know which of my products/services are the most profitable.\n\nMy business: [describe].\nMy products/services: [list with price].\nCosts per product: [list if known].\n\nGive me: comparative analysis in a table, margin per product, the 3 that contribute most to the business, the 3 I should review or discontinue and pricing recommendations."}},{"id":"fin-004","area":"finance","es":{"t":"Plan para reducir cartera vencida","d":"Estrategia clara para cobrar lo que te deben.","p":"Tengo cartera vencida y necesito un plan para cobrarla sin perder a los clientes.\n\nVolumen actual de cartera vencida: [monto y % del total].\nTipo de clientes deudores: [describir].\nTiempo promedio de mora: [días].\n\nDame: estrategia por tipo de mora (15/30/60/90 días), 4 mensajes escalonados de cobro, cuándo y cómo escalar legalmente y políticas preventivas para evitar futura mora."},"en":{"t":"Plan to reduce overdue receivables","d":"Clear strategy to collect what is owed to you.","p":"I have overdue receivables and need a plan to collect them without losing customers.\n\nCurrent volume of overdue receivables: [amount and % of total].\nType of debtor clients: [describe].\nAverage days past due: [days].\n\nGive me: strategy by aging (15/30/60/90 days), 4 staged collection messages, when and how to escalate legally and preventive policies to avoid future overdue receivables."}},{"id":"fin-005","area":"finance","es":{"t":"Calcular punto de equilibrio","d":"Cuántas unidades o pesos necesitas para no perder dinero.","p":"Quiero saber cuál es mi punto de equilibrio para tomar mejores decisiones.\n\nMi negocio: [describir].\nGastos fijos mensuales: [monto].\nPrecio promedio de venta: [monto].\nCosto variable por unidad: [monto].\n\nDame: cálculo del punto de equilibrio en unidades y pesos, análisis de qué pasaría si subo o bajo el precio, escenarios con diferentes volúmenes de venta y recomendaciones para mejorar la posición."},"en":{"t":"Calculate break-even point","d":"How many units or how much money you need to avoid losing money.","p":"I want to know my break-even point to make better decisions.\n\nMy business: [describe].\nMonthly fixed costs: [amount].\nAverage selling price: [amount].\nVariable cost per unit: [amount].\n\nGive me: calculation of the break-even point in units and money, analysis of what would happen if I raise or lower the price, scenarios with different sales volumes and recommendations to improve the position."}},{"id":"fin-006","area":"finance","es":{"t":"Evaluar una inversión","d":"Decisión informada sobre si vale la pena una inversión nueva.","p":"Estoy considerando una inversión importante en mi negocio y quiero evaluarla seriamente.\n\nLa inversión: [describir].\nCosto total: [monto].\nIngreso esperado: [monto y plazo].\nRiesgos identificados: [listar].\n\nDame: análisis de retorno esperado, tiempo de recuperación, escenarios optimista/realista/pesimista, riesgos detallados con mitigación y recomendación final con justificación."},"en":{"t":"Evaluate an investment","d":"Informed decision about whether a new investment is worth it.","p":"I am considering a major investment in my business and want to evaluate it seriously.\n\nThe investment: [describe].\nTotal cost: [amount].\nExpected income: [amount and timeframe].\nIdentified risks: [list].\n\nGive me: analysis of expected return, payback period, optimistic/realistic/pessimistic scenarios, risks detailed with mitigation, and a final recommendation with justification."}},{"id":"fin-007","area":"finance","es":{"t":"Reporte financiero mensual","d":"Reporte ejecutivo claro para revisar el negocio en 10 minutos.","p":"Quiero un formato de reporte financiero mensual ejecutivo para revisar mi negocio rápido.\n\nMi negocio: [describir].\nQué decisiones necesito tomar basadas en el reporte: [crecer / ajustar costos / invertir].\n\nDame: estructura del reporte (1-2 páginas máximo), KPIs clave a mostrar, gráficos sugeridos, comentarios automáticos según resultados y plantilla lista para llenar mes a mes."},"en":{"t":"Monthly financial report","d":"Clear executive report to review the business in 10 minutes.","p":"I want a format for a monthly executive financial report to review my business quickly.\n\nMy business: [describe].\nDecisions I need to make based on the report: [grow / adjust costs / invest].\n\nGive me: report structure (1-2 pages maximum), key KPIs to display, suggested charts, automated comments based on results, and a template ready to fill in month by month."}},{"id":"fin-008","area":"finance","es":{"t":"Plan para conseguir financiamiento","d":"Estrategia para acceder a crédito o inversión.","p":"Necesito financiamiento para mi negocio y quiero prepararme bien.\n\nMonto que necesito: [monto].\nPara qué lo necesito: [capital de trabajo / inversión / expansión].\nMi negocio: [tamaño y antigüedad].\n\nDame: opciones de financiamiento más adecuadas, documentos que voy a necesitar, cómo presentar mi negocio ante el banco/inversor, errores comunes a evitar y plan B si me dicen que no."},"en":{"t":"Plan to obtain financing","d":"Strategy to access credit or investment.","p":"I need financing for my business and want to prepare well.\n\nAmount I need: [amount].\nWhat I need it for: [working capital / investment / expansion].\nMy business: [size and age].\n\nGive me: the most suitable financing options, documents I will need, how to present my business to the bank/investor, common mistakes to avoid, and a plan B if they say no."}},{"id":"fin-009","area":"finance","es":{"t":"Ajustar precios","d":"Estrategia para subir precios sin perder clientes.","p":"Necesito subir mis precios y tengo miedo de perder clientes.\n\nMi producto/servicio: [describir].\nPrecio actual: [monto].\nAumento que necesito: [%].\nCosto principal que subió: [describir].\n\nDame: cuánto subir y con qué frecuencia, cómo comunicarlo a clientes actuales, justificación clara que entiendan, 3 alternativas para clientes que no acepten el nuevo precio y plan de implementación."},"en":{"t":"Adjust prices","d":"Strategy to raise prices without losing customers.","p":"I need to raise my prices and I'm afraid of losing customers.\n\nMy product/service: [describe].\nCurrent price: [amount].\nIncrease I need: [%].\nMain cost that increased: [describe].\n\nGive me: how much to increase and how often, how to communicate it to current customers, a clear justification they will understand, 3 alternatives for customers who don't accept the new price, and an implementation plan."}},{"id":"fin-010","area":"finance","es":{"t":"Detectar fugas de dinero","d":"Diagnóstico de dónde se escapa el dinero del negocio.","p":"Siento que el dinero se me escapa y no sé bien dónde. Ayúdame a detectar fugas.\n\nMi negocio: [describir].\nIngresos: [monto].\nGastos conocidos: [listar].\nLo que sospecho: [intuiciones].\n\nDame: las 10 fugas más comunes en negocios como el mío, preguntas para investigar cada una, métricas para detectarlas y plan de acción priorizado por impacto."},"en":{"t":"Detect money leaks","d":"Diagnosis of where the business is losing money.","p":"I feel money is slipping away and I don't know where. Help me detect leaks.\n\nMy business: [describe].\nRevenue: [amount].\nKnown expenses: [list].\nWhat I suspect: [intuitions].\n\nGive me: the 10 most common leaks in businesses like mine, questions to investigate each one, metrics to detect them, and an action plan prioritized by impact."}},{"id":"leg-001","area":"legal","es":{"t":"Contrato de prestación de servicios","d":"Borrador de contrato profesional listo para revisar con abogado.","p":"Necesito un contrato de prestación de servicios para mis clientes.\n\nTipo de servicio que presto: [describir].\nDuración típica del servicio: [tiempo].\nForma de pago: [describir].\nQué quiero proteger: [listar puntos clave].\n\nDame un borrador con: objeto, plazo, obligaciones de ambas partes, forma de pago, confidencialidad, propiedad intelectual, terminación anticipada y cláusulas de resolución de conflictos. (Después un abogado debe revisarlo)."},"en":{"t":"Service agreement","d":"Draft of a professional contract ready to review with a lawyer.","p":"I need a service agreement for my clients.\n\nType of service I provide: [describe].\nTypical duration of the service: [time].\nPayment terms: [describe].\nWhat I want to protect: [list key points].\n\nGive me a draft with: scope/objective, term, obligations of both parties, payment terms, confidentiality, intellectual property, early termination, and dispute resolution clauses. (A lawyer should review it afterwards)."}},{"id":"leg-002","area":"legal","es":{"t":"Política de privacidad","d":"Política de privacidad clara y profesional para tu web.","p":"Necesito una política de privacidad para mi sitio web/app.\n\nMi negocio: [describir].\nDatos que recolecto: [listar].\nPara qué uso esos datos: [describir].\nPaís principal de mis usuarios: [país].\n\nDame: política de privacidad clara y profesional, en lenguaje entendible, con secciones de datos recolectados, uso, compartición, derechos del usuario, cookies y cómo contactarnos."},"en":{"t":"Privacy policy","d":"Clear and professional privacy policy for your website.","p":"I need a privacy policy for my website/app.\n\nMy business: [describe].\nData I collect: [list].\nWhat I use that data for: [describe].\nMain country of my users: [country].\n\nGive me: a clear and professional privacy policy, in understandable language, with sections on collected data, usage, sharing, user rights, cookies, and how to contact us."}},{"id":"leg-003","area":"legal","es":{"t":"Términos y condiciones","d":"T&C profesionales que protegen tu negocio.","p":"Necesito Términos y Condiciones para mi sitio web/servicio.\n\nMi negocio: [describir].\nLo que ofrezco: [producto/servicio].\nPaís principal de mis clientes: [país].\nLo que necesito proteger: [listar].\n\nDame: T&C completos con secciones de aceptación, uso del servicio, pagos y reembolsos, limitación de responsabilidad, propiedad intelectual, ley aplicable y cómo modificarlos en el futuro."},"en":{"t":"Terms and Conditions","d":"Professional T&Cs that protect your business.","p":"I need Terms and Conditions for my website/service.\n\nMy business: [describe].\nWhat I offer: [product/service].\nPrimary country of my customers: [country].\nWhat I need to protect: [list].\n\nGive me: full T&Cs with sections on acceptance, use of the service, payments and refunds, limitation of liability, intellectual property, governing law, and how to modify them in the future."}},{"id":"leg-004","area":"legal","es":{"t":"Carta de cobro legal","d":"Carta formal que precede acciones legales.","p":"Un cliente no me paga y necesito enviarle una carta formal antes de tomar acciones legales.\n\nDeuda: [monto y desde cuándo].\nServicio prestado: [describir].\nIntentos previos de cobro: [listar].\n\nDame: carta formal de requerimiento de pago, plazo razonable para pagar, consecuencias claras si no paga, tono firme pero profesional y opciones de pago para facilitar el acuerdo."},"en":{"t":"Formal demand letter (pre-litigation)","d":"Formal letter that precedes legal action.","p":"A client hasn't paid me and I need to send a formal letter before taking legal action.\n\nDebt: [amount and since when].\nService provided: [describe].\nPrevious collection attempts: [list].\n\nGive me: a formal demand letter for payment, a reasonable deadline to pay, clear consequences if they do not pay, a firm but professional tone, and payment options to facilitate a settlement."}},{"id":"leg-005","area":"legal","es":{"t":"Acuerdo de confidencialidad (NDA)","d":"NDA listo para firmar con socios, proveedores o empleados.","p":"Necesito un acuerdo de confidencialidad (NDA) para una situación específica.\n\nSituación: [proveedor / empleado / socio / inversor].\nQué información quiero proteger: [describir].\nDuración deseada: [tiempo].\n\nDame: NDA completo en lenguaje claro, con secciones de definición de información confidencial, obligaciones, excepciones, duración, sanciones y ley aplicable."},"en":{"t":"Non-disclosure Agreement (NDA)","d":"NDA ready to sign with partners, suppliers, or employees.","p":"I need a non-disclosure agreement (NDA) for a specific situation.\n\nSituation: [supplier / employee / partner / investor].\nWhat information I want to protect: [describe].\nDesired duration: [time].\n\nGive me: a complete NDA in clear language, with sections defining confidential information, obligations, exceptions, duration, remedies, and governing law."}},{"id":"leg-006","area":"legal","es":{"t":"Respuesta a queja legal","d":"Respuesta formal y profesional ante un reclamo legal.","p":"Recibí una queja con tono legal y necesito responder de forma profesional sin admitir responsabilidad de más.\n\nLo que dice el reclamante: [pegar].\nMi versión de los hechos: [describir].\nLo que estoy dispuesto a ofrecer: [opciones].\n\nDame: respuesta formal, qué admitir y qué NO, ofrecimiento concreto si corresponde, próximos pasos sugeridos y recomendación de consultar abogado si es serio."},"en":{"t":"Response to legal complaint","d":"Formal, professional response to a legal claim.","p":"I received a complaint with legal tone and I need to respond professionally without admitting more liability than necessary.\n\nWhat the claimant says: [paste].\nMy version of the facts: [describe].\nWhat I am willing to offer: [options].\n\nGive me: a formal response, what to admit and what NOT to admit, a concrete offer if applicable, suggested next steps, and a recommendation to consult a lawyer if it is serious."}},{"id":"leg-007","area":"legal","es":{"t":"Política de uso de datos","d":"Política interna que protege la información de clientes.","p":"Quiero una política interna de manejo de datos para mi equipo.\n\nMi negocio: [describir].\nDatos sensibles que manejamos: [describir].\nQuién tiene acceso: [roles].\n\nDame: política interna de manejo de datos, reglas claras para el equipo, qué hacer en caso de fuga, capacitación obligatoria sugerida y sanciones por incumplimiento."},"en":{"t":"Data usage policy","d":"Internal policy that protects customer information.","p":"I want an internal data handling policy for my team.\n\nMy business: [describe].\nSensitive data we handle: [describe].\nWho has access: [roles].\n\nGive me: an internal data handling policy, clear rules for the team, steps to take in case of a breach, suggested mandatory training, and sanctions for non-compliance."}},{"id":"leg-008","area":"legal","es":{"t":"Carta de no objeción","d":"Carta formal de no objeción para uso de imagen, contenido o referencias.","p":"Necesito una carta de no objeción/autorización formal.\n\nQué se autoriza: [uso de imagen / testimonio / referencia profesional / contenido].\nQuién autoriza: [persona/empresa].\nDuración: [tiempo].\n\nDame: carta formal lista para firmar, con alcance claro de la autorización, duración, condiciones de revocación y firma."},"en":{"t":"No-objection/authorization letter","d":"Formal no-objection letter for use of image, content, or references.","p":"I need a no-objection/authorization letter.\n\nWhat is authorized: [use of image / testimonial / professional reference / content].\nWho authorizes: [person/company].\nDuration: [time].\n\nGive me: a formal letter ready to sign, with a clear scope of the authorization, duration, conditions for revocation, and signature block."}},{"id":"leg-009","area":"legal","es":{"t":"Acuerdo entre socios","d":"Borrador de acuerdo entre socios que previene conflictos futuros.","p":"Voy a formalizar un acuerdo entre socios y quiero un borrador profesional para revisar con abogado.\n\nNúmero de socios: [#].\nAportes de cada uno: [dinero / trabajo / contactos].\n% de participación: [describir].\nRoles: [describir].\n\nDame: borrador con aportes, distribución de utilidades, toma de decisiones, qué pasa si alguien se va, qué pasa si entra un inversor y resolución de conflictos. (Pasar a abogado para revisión final)."},"en":{"t":"Partnership agreement","d":"Draft partnership agreement that prevents future conflicts.","p":"I am going to formalize a partnership agreement and I want a professional draft to review with a lawyer.\n\nNumber of partners: [#].\nContributions from each: [money / work / contacts].\n% ownership: [describe].\nRoles: [describe].\n\nGive me: a draft covering contributions, profit distribution, decision-making, what happens if someone leaves, what happens if an investor joins, and conflict resolution. (Provide to a lawyer for final review.)"}},{"id":"leg-010","area":"legal","es":{"t":"Reglamento interno de la empresa","d":"Reglamento que establece reglas claras de convivencia laboral.","p":"Necesito un reglamento interno de trabajo para mi empresa.\n\nTamaño del equipo: [#].\nRubro: [describir].\nQué quiero regular: [horarios / vacaciones / uso de redes / vestimenta / disciplina].\n\nDame: reglamento profesional con secciones claras, redacción simple, derechos y deberes balanceados, proceso disciplinario justo y proceso de comunicación al equipo."},"en":{"t":"Company internal regulations","d":"Regulations that establish clear workplace rules.","p":"I need an internal work regulation for my company.\n\nTeam size: [#].\nIndustry: [describe].\nWhat I want to regulate: [schedules / vacations / social media use / dress code / discipline].\n\nGive me: a professional regulation with clear sections, plain language, balanced rights and duties, a fair disciplinary process, and a process for communicating it to the team."}},{"id":"ec-001","area":"ecommerce","es":{"t":"Descripción de producto que vende","d":"Texto que convierte visitantes en compradores.","p":"Necesito una descripción que venda para un producto en mi tienda online.\n\nProducto: [nombre y características].\nA quién va dirigido: [perfil].\nLo que lo hace especial: [diferenciales].\nPrecio: [monto].\n\nDame: título llamativo, descripción corta (2 líneas), descripción larga con beneficios, especificaciones técnicas en lista, palabras clave para SEO y CTA fuerte al final."},"en":{"t":"Product Description That Sells","d":"Copy that turns visitors into buyers.","p":"I need a sales-focused description for a product in my online store.\n\nProduct: [name and features].\nTarget audience: [profile].\nWhat makes it special: [differentiators].\nPrice: [amount].\n\nGive me: attention-grabbing title, short description (2 lines), long description with benefits, technical specifications as a list, SEO keywords and a strong CTA at the end."}},{"id":"ec-002","area":"ecommerce","es":{"t":"Optimizar página de checkout","d":"Recomendaciones concretas para reducir abandono de carrito.","p":"Tengo mucho abandono de carrito en mi tienda online y quiero reducirlo.\n\nMi tienda: [describir producto].\n% actual de abandono: [si lo sabes].\nPasos actuales del checkout: [describir].\nMétodos de pago aceptados: [listar].\n\nDame: 7 mejoras concretas priorizadas por impacto, qué textos y botones cambiar, qué señales de confianza agregar y email de recuperación de carrito."},"en":{"t":"Optimize Checkout Page","d":"Concrete recommendations to reduce cart abandonment.","p":"I have high cart abandonment on my online store and want to reduce it.\n\nMy store: [describe product].\nCurrent abandonment %: [if known].\nCurrent checkout steps: [describe].\nAccepted payment methods: [list].\n\nGive me: 7 concrete improvements prioritized by impact, which texts and buttons to change, what trust signals to add and a cart recovery email."}},{"id":"ec-003","area":"ecommerce","es":{"t":"Estrategia de cross-sell y up-sell","d":"Plan para vender más a cada cliente.","p":"Quiero aumentar el ticket promedio de mis ventas con cross-sell y up-sell.\n\nMi tienda: [describir].\nProductos principales: [listar].\nTicket promedio actual: [monto].\nMeta: [aumento %].\n\nDame: estrategia clara con productos a cruzar, cuándo y dónde mostrarlos en el viaje del cliente (carrito, post-compra, email), copy para cada momento y combos sugeridos con descuento."},"en":{"t":"Cross-sell and Up-sell Strategy","d":"Plan to sell more to each customer.","p":"I want to increase my average order value with cross-sell and up-sell.\n\nMy store: [describe].\nMain products: [list].\nCurrent average order value: [amount].\nGoal: [increase %].\n\nGive me: a clear strategy with products to cross-sell, when and where to show them in the customer journey (cart, post-purchase, email), copy for each moment and suggested bundles with discounts."}},{"id":"ec-004","area":"ecommerce","es":{"t":"Email de carrito abandonado","d":"Secuencia de 3 emails para recuperar carritos perdidos.","p":"Necesito una secuencia de emails para recuperar carritos abandonados en mi tienda online.\n\nMi tienda: [describir].\nProductos principales: [listar].\nMargen para descuentos: [%].\n\nDame: secuencia de 3 emails (2 horas / 24 horas / 72 horas) con asuntos que abran, copy persuasivo pero no agresivo, oferta progresiva de descuento y CTA claro en cada uno."},"en":{"t":"Abandoned Cart Email","d":"Sequence of 3 emails to recover lost carts.","p":"I need a sequence of emails to recover abandoned carts in my online store.\n\nMy store: [describe].\nMain products: [list].\nMargin available for discounts: [%].\n\nGive me: a sequence of 3 emails (2 hours / 24 hours / 72 hours) with subject lines that get opens, persuasive but not aggressive copy, a progressive discount offer and a clear CTA in each."}},{"id":"ec-005","area":"ecommerce","es":{"t":"Lanzamiento de nuevo producto","d":"Plan completo para lanzar un producto nuevo en tu tienda.","p":"Voy a lanzar un producto nuevo en mi tienda online y quiero un plan completo.\n\nProducto: [describir].\nFecha de lanzamiento: [cuándo].\nAudiencia: [perfil].\nPrecio: [monto].\n\nDame: cuenta regresiva 14 días antes, email pre-lanzamiento, día del lanzamiento, post-lanzamiento, anuncios para Meta Ads y métricas a seguir."},"en":{"t":"New Product Launch","d":"Complete plan to launch a new product in your store.","p":"I'm launching a new product in my online store and want a complete plan.\n\nProduct: [describe].\nLaunch date: [when].\nAudience: [profile].\nPrice: [amount].\n\nGive me: a 14-day countdown, pre-launch email, launch day, post-launch, ads for Meta Ads and metrics to track."}},{"id":"ec-006","area":"ecommerce","es":{"t":"Análisis de productos estrella","d":"Identificar qué productos te hacen ganar más.","p":"Quiero saber cuáles son mis productos estrella y cuáles debería discontinuar.\n\nMi tienda: [describir].\nVolumen de productos: [#].\nVentas mensuales aproximadas: [monto].\n\nDame: clasificación tipo ABC (cuáles son los 20% que dan el 80%), criterios para discontinuar productos, recomendaciones de cómo destacar los estrella y reemplazos para los que se van."},"en":{"t":"Analysis of Top Products","d":"Identify which products make you the most profit.","p":"I want to know which of my products are star performers and which I should discontinue.\n\nMy store: [describe].\nProduct count: [#].\nApproximate monthly sales: [amount].\n\nGive me: an ABC classification (which 20% deliver 80%), criteria to discontinue products, recommendations on how to highlight the stars and replacements for those you discontinue."}},{"id":"ec-007","area":"ecommerce","es":{"t":"Programa de fidelización","d":"Sistema de recompensas que hace que los clientes vuelvan.","p":"Quiero crear un programa de fidelización para mi tienda online.\n\nMi tienda: [describir].\nTicket promedio: [monto].\nFrecuencia de compra de clientes recurrentes: [veces/mes].\nMargen de maniobra para premios: [% del ticket].\n\nDame: estructura del programa (niveles, puntos), recompensas que motiven sin afectar margen, cómo comunicarlo, cómo medir su efectividad y errores a evitar."},"en":{"t":"Loyalty Program","d":"Rewards system that brings customers back.","p":"I want to create a loyalty program for my online store.\n\nMy store: [describe].\nAverage order value: [amount].\nPurchase frequency of repeat customers: [times/month].\nBudget margin for rewards: [% of the ticket].\n\nGive me: program structure (tiers, points), rewards that motivate without hurting margin, how to communicate it, how to measure its effectiveness and mistakes to avoid."}},{"id":"ec-008","area":"ecommerce","es":{"t":"Reseñas y testimonios para producto","d":"Estrategia para conseguir reseñas reales que impulsen ventas.","p":"Quiero conseguir más reseñas de mis clientes para mi tienda.\n\nMi tienda: [describir].\nVolumen de pedidos mensuales: [#].\n% actual que deja reseña: [si lo sabes].\n\nDame: email post-compra para pedir reseña, incentivo razonable que no compre la opinión, plantilla simple para responder reseñas (buenas y malas) y cómo mostrar las reseñas en la web para que vendan."},"en":{"t":"Reviews and Testimonials for Product","d":"Strategy to get real reviews that boost sales.","p":"I want to get more customer reviews for my store.\n\nMy store: [describe].\nMonthly order volume: [#].\nCurrent % that leave a review: [if known].\n\nGive me: post-purchase email to ask for a review, a reasonable incentive that doesn't buy the opinion, a simple template to respond to reviews (positive and negative) and how to display reviews on the website so they sell."}},{"id":"ec-009","area":"ecommerce","es":{"t":"Estrategia de envíos","d":"Política de envío que protege margen y satisface al cliente.","p":"Necesito definir mi política de envíos para mi tienda online.\n\nMi tienda: [describir].\nUbicación: [país/ciudad].\nProducto típico: [peso/volumen].\nMárgenes: [% promedio].\n\nDame: opciones de envío recomendadas, umbral de envío gratis, cómo comunicarlo claramente, política de demoras y cómo manejar zonas remotas."},"en":{"t":"Shipping strategy","d":"Shipping policy that protects margins and satisfies customers.","p":"I need to define my shipping policy for my online store.\n\nMy store: [describe].\nLocation: [country/city].\nTypical product: [weight/volume].\nMargins: [% average].\n\nGive me: recommended shipping options, free-shipping threshold, how to communicate it clearly, delay policy and how to handle remote zones."}},{"id":"ec-010","area":"ecommerce","es":{"t":"Promoción de fin de mes","d":"Promo que mueve ventas sin destruir el margen.","p":"Quiero lanzar una promoción de fin de mes para mover stock y ventas.\n\nMi tienda: [describir].\nProductos a promover: [listar].\nMargen disponible para descuento: [%].\nDuración deseada: [días].\n\nDame: tipo de promoción ideal (descuento / 2x1 / envío gratis), copy para anunciarla, email a base de clientes, posts para redes y cómo medir su éxito."},"en":{"t":"End-of-month promotion","d":"Promotion that moves sales without eroding margin.","p":"I want to launch an end-of-month promotion to move stock and sales.\n\nMy store: [describe].\nProducts to promote: [list].\nMargin available for discount: [%].\nDesired duration: [days].\n\nGive me: ideal type of promotion (discount / buy-one-get-one / free shipping), ad copy to announce it, email to the customer base, social posts and how to measure its success."}},{"id":"dev-001","area":"dev","es":{"t":"Automatizar tarea repetitiva","d":"Automatización que ahorra horas semanales.","p":"Tengo una tarea repetitiva que quiero automatizar.\n\nTarea: [describir paso a paso lo que hago manualmente].\nFrecuencia: [diaria / semanal].\nHerramientas que uso: [listar].\nResultado esperado: [qué debe quedar al final].\n\nDame: análisis de qué se puede automatizar, herramientas recomendadas (gratuitas si es posible), código o configuración paso a paso y cómo probarlo antes de usarlo en serio."},"en":{"t":"Automate repetitive task","d":"Automation that saves hours weekly.","p":"I have a repetitive task I want to automate.\n\nTask: [describe step-by-step what I do manually].\nFrequency: [daily / weekly].\nTools I use: [list].\nExpected result: [what should be the final result].\n\nGive me: analysis of what can be automated, recommended tools (free if possible), code or step-by-step configuration and how to test it before using it in production."}},{"id":"dev-002","area":"dev","es":{"t":"Crear base de datos para tu negocio","d":"Base de datos simple para organizar clientes, ventas o inventario.","p":"Necesito una base de datos para organizar información de mi negocio.\n\nQué quiero organizar: [clientes / ventas / inventario / proyectos].\nQué información necesito guardar: [listar campos].\nQuién la va a usar: [yo solo / equipo].\nHerramienta preferida: [Excel / Google Sheets / Airtable / Notion].\n\nDame: estructura de tablas y campos, fórmulas o automatizaciones útiles, vistas/reportes recomendados y cómo importar datos que ya tienes."},"en":{"t":"Create a database for your business","d":"Simple database to organize customers, sales or inventory.","p":"I need a database to organize information for my business.\n\nWhat I want to organize: [customers / sales / inventory / projects].\nWhich information I need to store: [list fields].\nWho will use it: [just me / team].\nPreferred tool: [Excel / Google Sheets / Airtable / Notion].\n\nGive me: table and field structure, useful formulas or automations, recommended views/reports and how to import the data you already have."}},{"id":"dev-003","area":"dev","es":{"t":"Conectar dos herramientas (integración)","d":"Integración entre apps para que la información fluya sola.","p":"Quiero conectar dos herramientas que uso para que la información fluya sin pasarla a mano.\n\nHerramienta A: [origen, ej: WhatsApp Business].\nHerramienta B: [destino, ej: Google Sheets].\nQué quiero que pase: [describir flujo].\nFrecuencia: [tiempo real / diaria].\n\nDame: opciones de integración (Zapier, Make, n8n, etc), cuál recomiendas y por qué, paso a paso para configurarla y cómo probar que funciona."},"en":{"t":"Connect two tools (integration)","d":"Integration between apps so information flows automatically.","p":"I want to connect two tools I use so information flows without manual transfer.\n\nTool A: [source, e.g., WhatsApp Business].\nTool B: [destination, e.g., Google Sheets].\nWhat I want to happen: [describe the flow].\nFrequency: [real time / daily].\n\nGive me: integration options (Zapier, Make, n8n, etc.), which you recommend and why, step-by-step setup and how to test that it works."}},{"id":"dev-004","area":"dev","es":{"t":"Debug — qué hago si algo no funciona","d":"Diagnóstico claro de por qué falla un sistema o proceso.","p":"Algo no está funcionando en mi sistema/proceso y necesito ayuda para diagnosticar.\n\nQué debería pasar: [describir].\nQué está pasando: [describir el síntoma].\nQué cambió recientemente: [describir si recuerdas].\nMensaje de error si lo hay: [pegar].\n\nDame: las 5 causas más probables ordenadas por probabilidad, cómo verificar cada una y solución paso a paso para cada caso."},"en":{"t":"Debug — what to do if something doesn't work","d":"Clear diagnosis of why a system or process is failing.","p":"Something isn't working in my system/process and I need help diagnosing it.\n\nWhat should happen: [describe].\nWhat is happening: [describe the symptom].\nWhat changed recently: [describe if you remember].\nError message, if any: [paste].\n\nGive me: the 5 most likely causes ordered by probability, how to check each one and step-by-step fixes for each case."}},{"id":"dev-005","area":"dev","es":{"t":"Crear panel/dashboard interno","d":"Tablero simple para ver el negocio en una pantalla.","p":"Quiero un panel donde pueda ver el estado de mi negocio de un vistazo.\n\nMi negocio: [describir].\nDatos que quiero monitorear: [ventas / leads / inventario / soporte].\nHerramientas donde están los datos: [listar].\nQuién lo va a ver: [yo / equipo].\n\nDame: KPIs que debe mostrar, estructura visual (qué arriba, qué abajo), herramientas recomendadas para construirlo y plan paso a paso para implementarlo."},"en":{"t":"Create internal dashboard","d":"Simple dashboard to see the business at a glance.","p":"I want a dashboard where I can see the state of my business at a glance.\n\nMy business: [describe].\nData I want to monitor: [sales / leads / inventory / support].\nTools where the data lives: [list].\nWho will view it: [me / team].\n\nGive me: KPIs it should show, visual layout (what goes on top, what goes below), recommended tools to build it and a step-by-step implementation plan."}},{"id":"dev-006","area":"dev","es":{"t":"Crear formulario web","d":"Formulario que captura información ordenada de clientes.","p":"Necesito un formulario web para capturar información de mis clientes/prospectos.\n\nPropósito: [contactar / cotizar / agendar / encuesta].\nCampos necesarios: [listar].\nDonde irá la información: [email / hoja de cálculo / CRM].\n\nDame: estructura del formulario, validaciones útiles, mensajes de éxito y error, integración recomendada y cómo embebido en mi web/Instagram."},"en":{"t":"Create web form","d":"Form that captures organized customer information.","p":"I need a web form to capture information from my customers/prospects.\n\nPurpose: [contact / quote / schedule / survey].\nRequired fields: [list].\nWhere the information will go: [email / spreadsheet / CRM].\n\nGive me: form structure, useful validations, success and error messages, recommended integration and how to embed it on my website/Instagram."}},{"id":"dev-007","area":"dev","es":{"t":"Migrar de Excel a sistema","d":"Plan para pasar de Excel a una herramienta más profesional.","p":"Estoy creciendo y mi Excel ya no me alcanza. Quiero migrar a algo más profesional sin perder datos.\n\nLo que tengo en Excel: [describir].\nProblemas actuales: [duplicados / lentitud / errores].\nQuién más necesita acceso: [equipo].\nPresupuesto: [monto/mes].\n\nDame: 3 herramientas recomendadas según mi caso, comparación de pros y contras, plan de migración por etapas y cómo capacitar al equipo."},"en":{"t":"Migrate from Excel to a system","d":"Plan to move from Excel to a more professional tool.","p":"I'm growing and my Excel no longer meets my needs. I want to migrate to something more professional without losing data.\n\nWhat I have in Excel: [describe].\nCurrent problems: [duplicates / slowness / errors].\nWho else needs access: [team].\nBudget: [amount/month].\n\nGive me: 3 tools recommended for my case, a comparison of pros and cons, a staged migration plan and how to train the team."}},{"id":"dev-008","area":"dev","es":{"t":"Plantilla de planilla profesional","d":"Hoja de cálculo lista para usar con fórmulas y diseño limpio.","p":"Necesito una plantilla de planilla de cálculo profesional para una tarea específica.\n\nTarea: [presupuesto / control de stock / seguimiento de ventas / etc].\nDatos a registrar: [listar columnas].\nQuién la va a usar: [yo / equipo].\nHerramienta: [Excel / Google Sheets].\n\nDame: estructura de columnas, fórmulas útiles, validaciones para evitar errores, gráficos recomendados y formato visual claro."},"en":{"t":"Professional spreadsheet template","d":"Ready-to-use spreadsheet with formulas and clean design.","p":"I need a professional spreadsheet template for a specific task.\n\nTask: [budget / inventory control / sales tracking / etc].\nData to record: [list columns].\nWho will use it: [me / team].\nTool: [Excel / Google Sheets].\n\nGive me: column structure, useful formulas, validations to avoid errors, recommended charts and a clear visual format."}},{"id":"dev-009","area":"dev","es":{"t":"Backup y seguridad de datos","d":"Plan claro para no perder información crítica del negocio.","p":"Quiero proteger los datos de mi negocio para no perderlos nunca.\n\nDónde están mis datos hoy: [computadora / nube / sistema].\nQué pasaría si los perdiera: [impacto].\nPresupuesto disponible para backup: [monto/mes].\n\nDame: estrategia 3-2-1 adaptada a mi caso, herramientas recomendadas (gratuitas y pagas), proceso paso a paso para implementarlo y cómo probar la recuperación."},"en":{"t":"Data backup and security","d":"Clear plan to avoid losing critical business information.","p":"I want to protect my business data so I never lose it.\n\nWhere my data is today: [computer / cloud / system].\nWhat would happen if I lost it: [impact].\nBudget available for backup: [amount/month].\n\nGive me: 3-2-1 strategy adapted to my case, recommended tools (free and paid), step-by-step process to implement it and how to test recovery."}},{"id":"dev-010","area":"dev","es":{"t":"Chatbot simple para WhatsApp/web","d":"Chatbot que responde preguntas básicas y libera tiempo.","p":"Quiero un chatbot simple para responder preguntas básicas de mis clientes y liberar tiempo.\n\nMi negocio: [describir].\nLas preguntas más frecuentes son: [listar].\nDonde lo necesito: [WhatsApp / web / Instagram].\n\nDame: flujo conversacional con las preguntas frecuentes resueltas, cuándo pasar a humano, herramientas recomendadas y cómo medir su efectividad."},"en":{"t":"Simple chatbot for WhatsApp/web","d":"Chatbot that answers basic questions and frees up time.","p":"I want a simple chatbot to answer basic customer questions and free up time.\n\nMy business: [describe].\nThe most frequent questions are: [list].\nWhere I need it: [WhatsApp / web / Instagram].\n\nGive me: conversational flow with the frequent questions answered, when to hand off to a human, recommended tools and how to measure its effectiveness."}},{"id":"dev-011","area":"dev","es":{"t":"Diseñar operación de WhatsApp Business con IA","d":"Mapa completo de cómo debería funcionar WhatsApp Business en tu negocio con IA y revisión humana.","p":"Quiero diseñar bien la operación de WhatsApp Business con IA para mi negocio.\n\nMi negocio: [describir].\nQué quiero lograr: [ventas / soporte / seguimiento / reservas / postventa].\nQué sistemas ya uso: [CRM / agenda / e-commerce / planilla / email].\nQué riesgos me preocupan: [respuestas incorrectas / demora / mensajes sensibles / quejas].\n\nDame: arquitectura operativa simple, qué debería automatizarse y qué no, cuándo debe intervenir un humano, qué datos mínimos necesita la IA, qué permisos/integraciones hacen falta y cómo hacer una primera prueba sin romper la atención al cliente."},"en":{"t":"Design WhatsApp Business operation with AI","d":"Complete map of how WhatsApp Business should work in your business with AI and human review.","p":"I want to properly design the WhatsApp Business operation with AI for my business.\n\nMy business: [describe].\nWhat I want to achieve: [sales / support / follow-up / bookings / after-sales].\nWhat systems I already use: [CRM / calendar / e-commerce / spreadsheet / email].\nWhat risks worry me: [incorrect answers / delays / sensitive messages / complaints].\n\nGive me: a simple operational architecture, what should be automated and what should not, when a human should intervene, the minimum data the AI needs, what permissions/integrations are required and how to run a first test without breaking customer service."}},{"id":"str-001","area":"strategy","es":{"t":"Plan estratégico anual","d":"Plan a 12 meses con objetivos, prioridades y revisión.","p":"Quiero armar el plan estratégico de mi empresa para los próximos 12 meses.\n\nMi negocio: [describir].\nLogros del año anterior: [destacar].\nLo que me preocupa: [riesgos / desafíos].\nDónde quiero estar en 12 meses: [meta].\n\nDame: análisis FODA, 5 objetivos estratégicos SMART, iniciativas clave por trimestre, KPIs principales y calendario de revisiones."},"en":{"t":"Annual strategic plan","d":"12-month plan with objectives, priorities, and review.","p":"I want to build my company's strategic plan for the next 12 months.\n\nMy business: [describe].\nAchievements of the past year: [highlight].\nWhat worries me: [risks / challenges].\nWhere I want to be in 12 months: [goal].\n\nGive me: SWOT analysis, 5 SMART strategic objectives, key initiatives by quarter, main KPIs and a review calendar."}},{"id":"str-002","area":"strategy","es":{"t":"Análisis FODA","d":"Diagnóstico claro de fortalezas, debilidades, oportunidades y amenazas.","p":"Quiero hacer un FODA serio de mi empresa para tomar mejores decisiones.\n\nMi negocio: [describir].\nMercado y competencia: [contexto].\nLo que siento que sé: [intuiciones].\n\nDame: FODA estructurado con 5 puntos en cada cuadrante, las 3 prioridades surgidas del cruce de cuadrantes (FO, FA, DO, DA) y plan de acción para cada prioridad."},"en":{"t":"SWOT analysis","d":"Clear diagnosis of strengths, weaknesses, opportunities, and threats.","p":"I want to do a serious SWOT of my company to make better decisions.\n\nMy business: [describe].\nMarket and competition: [context].\nWhat I feel I know: [intuitions].\n\nGive me: a structured SWOT with 5 points in each quadrant, the 3 priorities arising from the crossing of quadrants (SO, ST, WO, WT) and an action plan for each priority."}},{"id":"str-003","area":"strategy","es":{"t":"Tomar decisión difícil","d":"Marco claro para decidir cuando hay dudas serias.","p":"Tengo que tomar una decisión importante en mi negocio y necesito un marco objetivo.\n\nLa decisión: [describir opciones].\nQué está en juego: [impacto].\nPlazo para decidir: [tiempo].\nLo que más me preocupa: [riesgos].\n\nDame: criterios objetivos para evaluar, tabla comparativa de las opciones, escenarios optimista/realista/pesimista de cada opción, preguntas que debo responder antes y recomendación con justificación."},"en":{"t":"Make a difficult decision","d":"Clear framework to decide when there are serious doubts.","p":"I have to make an important decision in my business and I need an objective framework.\n\nThe decision: [describe options].\nWhat's at stake: [impact].\nDeadline to decide: [time].\nWhat worries me most: [risks].\n\nGive me: objective criteria to evaluate, a comparative table of the options, optimistic/realistic/pessimistic scenarios for each option, questions I must answer beforehand and a recommendation with justification."}},{"id":"str-011","area":"strategy","es":{"t":"Convertir WhatsApp en canal de ventas","d":"Plan comercial para usar WhatsApp Business como motor real de leads y cierres.","p":"Quiero convertir WhatsApp Business en un canal real de ventas para mi negocio.\n\nQué vendo: [describir].\nTicket promedio: [monto].\nCómo llegan hoy mis leads: [Meta Ads / orgánico / referidos / web].\nQué parte del proceso más se cae: [respuesta inicial / seguimiento / cierre / postventa].\n\nDame: estrategia comercial para WhatsApp, cómo captar mejor los leads, cómo calificarlos, qué mensajes usar en cada etapa, cuándo pasar a llamada o vendedor humano y qué métricas debo seguir para saber si WhatsApp sí está vendiendo."},"en":{"t":"Turn WhatsApp into a sales channel","d":"Commercial plan to use WhatsApp Business as a real lead and closing engine.","p":"I want to turn WhatsApp Business into a real sales channel for my business.\n\nWhat I sell: [describe].\nAverage ticket: [amount].\nHow my leads arrive today: [Meta Ads / organic / referrals / website].\nWhich part of the process fails most: [initial response / follow-up / closing / after-sales].\n\nGive me: commercial strategy for WhatsApp, how to capture leads better, how to qualify them, what messages to use at each stage, when to move to a call or human seller and what metrics I should track to know if WhatsApp is actually selling."}},{"id":"str-004","area":"strategy","es":{"t":"Plan de expansión","d":"Plan realista para crecer a nuevo mercado, ciudad o producto.","p":"Quiero expandir mi negocio y necesito un plan realista.\n\nMi negocio actual: [describir].\nA dónde quiero expandirme: [nueva ciudad / nuevo producto / nuevo segmento].\nPor qué creo que es buena idea: [hipótesis].\nRecursos disponibles: [tiempo / dinero / equipo].\n\nDame: validación de la hipótesis con preguntas clave, plan por fases, inversión estimada, riesgos principales y métricas para saber si funciona."},"en":{"t":"Expansion plan","d":"Realistic plan to grow into a new market, city or product.","p":"I want to expand my business and I need a realistic plan.\n\nMy current business: [describe].\nWhere I want to expand: [new city / new product / new segment].\nWhy I think it's a good idea: [hypothesis].\nResources available: [time / money / team].\n\nGive me: validation of the hypothesis with key questions, phased plan, estimated investment, main risks and metrics to know if it works."}},{"id":"str-005","area":"strategy","es":{"t":"Reunión de directorio","d":"Reunión de equipo directivo efectiva en 60 minutos.","p":"Quiero estructurar mejor mis reuniones de equipo directivo o socios.\n\nFrecuencia: [semanal / mensual].\nTamaño del equipo: [#].\nTipo de temas a tratar: [estratégicos / operativos / financieros].\n\nDame: agenda de 60 minutos, formato para llevarla bien, qué decisiones se toman en estas reuniones vs otras, plantilla de minuta y cómo cerrar con acciones claras y responsables."},"en":{"t":"Board/team meeting","d":"Effective leadership/team meeting in 60 minutes.","p":"I want to better structure my leadership or partners' team meetings.\n\nFrequency: [weekly / monthly].\nTeam size: [#].\nType of topics to cover: [strategic / operational / financial].\n\nGive me: 60-minute agenda, format to run it well, what decisions are made in these meetings vs others, meeting minutes template and how to close with clear accountable actions."}},{"id":"str-006","area":"strategy","es":{"t":"Definir misión, visión y valores","d":"Misión, visión y valores claros que inspiren al equipo.","p":"Quiero definir o redefinir la misión, visión y valores de mi empresa.\n\nMi negocio: [describir].\nPor qué empecé: [historia].\nLo que más me importa: [principios].\nDónde me veo en 5 años: [aspiración].\n\nDame: 3 propuestas de misión, 3 propuestas de visión, 5 valores con descripción y ejemplos reales de cómo se viven en el día a día."},"en":{"t":"Define mission, vision and values","d":"Clear mission, vision and values that inspire the team.","p":"I want to define or redefine my company's mission, vision and values.\n\nMy business: [describe].\nWhy I started: [story].\nWhat matters most to me: [principles].\nWhere I see myself in 5 years: [aspiration].\n\nGive me: 3 mission proposals, 3 vision proposals, 5 values with descriptions and real examples of how they are lived day-to-day."}},{"id":"str-007","area":"strategy","es":{"t":"Diagnóstico del negocio en 360°","d":"Radiografía clara del estado del negocio.","p":"Quiero un diagnóstico completo de mi negocio para saber dónde estoy.\n\nMi negocio: [describir].\nAntigüedad: [tiempo].\nTamaño actual: [empleados, facturación].\nLo que siento: [intuiciones sobre fortalezas/debilidades].\n\nDame: evaluación 1-10 de 8 dimensiones críticas (ventas, marketing, operaciones, finanzas, equipo, tecnología, atención, estrategia), las 3 más fuertes, las 3 más débiles y plan de mejora priorizado."},"en":{"t":"360° business diagnosis","d":"Clear snapshot of the business's condition.","p":"I want a complete diagnosis of my business to know where I stand.\n\nMy business: [describe].\nAge: [time].\nCurrent size: [employees, revenue].\nWhat I feel: [intuitions about strengths/weaknesses].\n\nGive me: 1-10 evaluation of 8 critical dimensions (sales, marketing, operations, finance, team, technology, customer service, strategy), the top 3 strengths, the top 3 weaknesses and a prioritized improvement plan."}},{"id":"str-008","area":"strategy","es":{"t":"Plan de salida o sucesión","d":"Plan para que el negocio funcione sin vos o para venderlo bien.","p":"Quiero preparar a mi negocio para que funcione sin mí o para una eventual venta.\n\nMi negocio: [describir].\nObjetivo: [quiero retirarme / vender / delegar más].\nPlazo deseado: [años].\n\nDame: qué hace que mi negocio sea vendible o autónomo, los 5 cambios estructurales más importantes, plan por años, riesgos y cómo aumentar el valor del negocio."},"en":{"t":"Exit or succession plan","d":"Plan for the business to run without you or to be sold well.","p":"I want to prepare my business to run without me or for an eventual sale.\n\nMy business: [describe].\nGoal: [I want to retire / sell / delegate more].\nDesired timeline: [years].\n\nGive me: what makes my business sellable or autonomous, the 5 most important structural changes, plan by years, risks and how to increase the business's value."}},{"id":"str-009","area":"strategy","es":{"t":"Comunicar mal año al equipo","d":"Comunicación honesta y motivadora ante un resultado malo.","p":"Tuvimos un año difícil y necesito comunicarlo al equipo sin destruir la moral.\n\nResultados: [describir].\nCausas principales: [describir].\nQué pasa con sueldos/bonos: [describir].\nVisión hacia adelante: [esperanza realista].\n\nDame: guion de reunión con el equipo, principios de comunicación honesta y motivadora, qué decir y qué NO decir y cómo cerrar con compromiso y claridad."},"en":{"t":"Communicate a bad year to the team","d":"Honest and motivating communication after a poor result.","p":"We had a difficult year and I need to communicate it to the team without destroying morale.\n\nResults: [describe].\nMain causes: [describe].\nWhat happens with salaries/bonuses: [describe].\nVision going forward: [realistic hope].\n\nGive me: meeting script with the team, principles for honest and motivating communication, what to say and what NOT to say and how to close with commitment and clarity."}},{"id":"str-010","area":"strategy","es":{"t":"Definir ventaja competitiva","d":"Claridad sobre qué te hace único y defendible en el mercado.","p":"Quiero definir con claridad qué hace único a mi negocio y por qué los clientes me eligen.\n\nMi negocio: [describir].\nMis competidores principales: [listar].\nLo que dicen mis clientes felices: [destacar].\nLo que yo creo que me diferencia: [hipótesis].\n\nDame: análisis de mi ventaja real vs percibida, cómo defenderla en el tiempo, cómo comunicarla mejor y plan para fortalecerla en los próximos 12 meses."},"en":{"t":"Define competitive advantage","d":"Clarity on what makes you unique and defensible in the market.","p":"I want to clearly define what makes my business unique and why customers choose me.\n\nMy business: [describe].\nMy main competitors: [list].\nWhat my happy customers say: [highlight].\nWhat I believe differentiates me: [hypothesis].\n\nGive me: analysis of my real vs perceived advantage, how to defend it over time, how to communicate it better and a plan to strengthen it over the next 12 months."}},{"id":"market-001","area":"market","es":{"t":"Auditar mi negocio local","d":"Revisa cómo aparece tu negocio en Google Maps, qué dicen tus reseñas y cómo te comparas con los negocios cercanos.","p":"Quiero una auditoría de cómo aparece mi negocio en Google Maps.\n\nNegocio: [nombre exacto, como aparece en Google].\nCiudad y país: [por ejemplo: Doral, Florida, EE. UU. / Medellín, Colombia].\nRubro: [restaurante / clínica dental / salón de belleza / taller / otro].\nIdioma de la respuesta: [español / inglés].\n\nSi te falta la ciudad, el país o el idioma, pregúntamelos antes de buscar. Busca mi negocio en Google Maps y lee sus reseñas más recientes. Dame:\n1. Cómo aparece mi ficha: dirección, teléfono, sitio web, horarios y calificación.\n2. Qué elogian y de qué se quejan mis clientes en las reseñas.\n3. Los negocios cercanos de mi rubro mejor calificados y cómo me comparo en calificación y cantidad de reseñas.\n4. Cinco acciones concretas para mejorar mi presencia y mis reseñas.\n\nSi un dato no aparece en Google Maps, dímelo en vez de suponerlo."},"en":{"t":"Audit my local business","d":"Reviews how your business shows up on Google Maps, what your reviews say, and how you compare with nearby businesses.","p":"I want an audit of how my business shows up on Google Maps.\n\nBusiness: [exact name, as it appears on Google].\nCity and country: [for example: Doral, Florida, USA / Medellín, Colombia].\nType of business: [restaurant / dental clinic / beauty salon / auto shop / other].\nLanguage for the answer: [English / Spanish].\n\nIf the city, the country, or the language is missing, ask me before searching. Look up my business on Google Maps and read its most recent reviews. Give me:\n1. How my listing appears: address, phone, website, hours, and rating.\n2. What my customers praise and complain about in the reviews.\n3. The best-rated nearby businesses of my type and how I compare on rating and number of reviews.\n4. Five concrete actions to improve my presence and my reviews.\n\nIf something doesn't appear on Google Maps, tell me instead of guessing."}},{"id":"market-002","area":"market","es":{"t":"Competidores cerca de mi negocio","d":"Encuentra a tus competidores de la zona en Google Maps y te muestra quién aparece primero en Google cuando buscan tu servicio.","p":"Quiero conocer a mis competidores cercanos.\n\nMi negocio: [qué vendes o qué servicio das].\nZona: [barrio o ciudad, y país — por ejemplo: Houston, Texas, EE. UU. / Chapinero, Bogotá, Colombia].\nIdioma de la respuesta: [español / inglés].\n\nSi te falta la zona, el país o el idioma, pregúntamelos antes de buscar. Busca en Google Maps los negocios de mi rubro en esa zona y arma una tabla con: nombre, dirección, teléfono, sitio web, calificación y número de reseñas. Después busca en Google mi servicio en esa zona (por ejemplo, \"dentista en Houston\") y dime quiénes aparecen primero, qué destacan en esos resultados y qué oportunidades tengo para diferenciarme.\n\nNo inventes precios ni datos que no aparezcan en los resultados."},"en":{"t":"Competitors near my business","d":"Finds your local competitors on Google Maps and shows who comes up first on Google when people search for your service.","p":"I want to know my nearby competitors.\n\nMy business: [what you sell or what service you offer].\nArea: [neighborhood or city, and country — for example: Houston, Texas, USA / Chapinero, Bogotá, Colombia].\nLanguage for the answer: [English / Spanish].\n\nIf the area, the country, or the language is missing, ask me before searching. Search Google Maps for businesses like mine in that area and build a table with: name, address, phone, website, rating, and number of reviews. Then search Google for my service in that area (for example, \"dentist in Houston\") and tell me who comes up first, what they highlight in those results, and what opportunities I have to stand out.\n\nDon't make up prices or details that don't appear in the results."}},{"id":"market-003","area":"market","es":{"t":"Ver los anuncios de la competencia","d":"Revisa los anuncios públicos de tus competidores y te resume qué mensajes y ofertas están usando.","p":"Quiero ver qué anuncios están publicando mis competidores.\n\nCompetidores: [nombre de la marca o su sitio web, de 1 a 3].\nPaís donde anuncian: [por ejemplo: Estados Unidos / México / Colombia].\nMi producto o servicio: [describir].\nIdioma de la respuesta: [español / inglés].\n\nSi te falta el país o el idioma, pregúntamelos antes de buscar. Busca en las bibliotecas públicas de anuncios que tengas disponibles los anuncios activos de cada competidor. De los anuncios de Facebook e Instagram, resume: mensajes principales, ofertas y precios que mencionan, llamados a la acción, desde cuándo están activos y qué formato usan (imagen, video o texto). De los anuncios de Google solo se sabe que se mostraron y cuándo: dime cuántos encontraste y desde cuándo se muestran, sin inventar su texto. Termina con ideas para mi próxima campaña.\n\nNo copies los anuncios tal cual. Si no encuentras anuncios de una marca, dímelo."},"en":{"t":"See competitors' ads","d":"Reviews your competitors' public ads and sums up the messages and offers they're using.","p":"I want to see what ads my competitors are running.\n\nCompetitors: [brand name or website, 1 to 3].\nCountry where they advertise: [for example: United States / Mexico / Colombia].\nMy product or service: [describe].\nLanguage for the answer: [English / Spanish].\n\nIf the country or the language is missing, ask me before searching. Search the public ad libraries you have available for each competitor's active ads. For Facebook and Instagram ads, sum up: main messages, offers and prices they mention, calls to action, how long they've been running, and the format they use (image, video, or text). For Google ads, all that's known is that they were shown and when: tell me how many you found and since when they've been running, without making up their text. Finish with ideas for my next campaign.\n\nDon't copy the ads word for word. If you can't find ads for a brand, tell me."}},{"id":"market-004","area":"market","es":{"t":"Comparar precios online","d":"Busca productos parecidos al tuyo en tiendas online de EE. UU., México, Colombia, Chile, Argentina y Brasil, y te arma una tabla de precios para comparar.","p":"Quiero comparar el precio de mi producto con lo que se vende en internet.\n\nProducto: [tipo, marca, tamaño o modelo].\nMi precio actual: [monto y moneda].\nCiudad y país: [Estados Unidos, México, Colombia, Chile, Argentina o Brasil — por ejemplo: Miami, EE. UU. / Ciudad de México / Bogotá, Colombia].\nIdioma de la respuesta: [español / inglés].\n\nSi te falta el país o el idioma, pregúntamelos antes de buscar; si mi país no es uno de esos, avísame en vez de buscar. Busca productos comparables en Google Shopping y arma una tabla con: producto, tienda, precio tal como aparece, calificación y número de reseñas si los hay, y si mencionan envío. Después dame el rango de precios (bajo, medio y alto), dónde queda mi precio y una recomendación.\n\nUsa solo los precios que encuentres; no los estimes."},"en":{"t":"Compare prices online","d":"Finds products like yours in online stores in the US, Mexico, Colombia, Chile, Argentina, and Brazil, and builds a price table to compare.","p":"I want to compare my product's price with what's sold online.\n\nProduct: [type, brand, size, or model].\nMy current price: [amount and currency].\nCity and country: [United States, Mexico, Colombia, Chile, Argentina, or Brazil — for example: Miami, USA / Mexico City / Bogotá, Colombia].\nLanguage for the answer: [English / Spanish].\n\nIf the country or the language is missing, ask me before searching; if my country isn't one of those, tell me instead of searching. Search Google Shopping for comparable products and build a table with: product, store, price as listed, rating and number of reviews if available, and whether they mention shipping. Then give me the price range (low, mid, and high), where my price falls, and a recommendation.\n\nOnly use prices you actually find; don't estimate them."}},{"id":"market-005","area":"market","es":{"t":"Detectar tendencias de mercado","d":"Compara qué tan buscados son varios temas o productos en Google y cómo cambia el interés con el tiempo.","p":"Quiero saber qué está creciendo en mi mercado.\n\nTemas o productos a comparar: [hasta 5 — por ejemplo: pilates, yoga, crossfit].\nPaís: [por ejemplo: Estados Unidos / Colombia / Argentina — o todo el mundo].\nPeriodo: [último mes / últimos 3 meses / último año / últimos 5 años].\nIdioma de la respuesta: [español / inglés].\n\nSi te falta el país, el periodo o el idioma, pregúntamelos antes de buscar. Usa Google Trends para comparar el interés de búsqueda en el tiempo y para ver las búsquedas relacionadas que más están subiendo. Dame: qué tema crece y cuál baja, en qué meses sube el interés, las búsquedas relacionadas que más crecen y tres ideas de producto, contenido o campaña para probar en los próximos 30 días.\n\nRecuerda que Google Trends muestra interés relativo (de 0 a 100), no cantidades de búsquedas."},"en":{"t":"Spot market trends","d":"Compares how much people search for several topics or products on Google and how interest changes over time.","p":"I want to know what's growing in my market.\n\nTopics or products to compare: [up to 5 — for example: pilates, yoga, crossfit].\nCountry: [for example: United States / Colombia / Argentina — or worldwide].\nTime range: [past month / past 3 months / past year / past 5 years].\nLanguage for the answer: [English / Spanish].\n\nIf the country, the time range, or the language is missing, ask me before searching. Use Google Trends to compare search interest over time and to see the related searches that are rising the most. Give me: which topic is growing and which is falling, the months when interest goes up, the fastest-rising related searches, and three product, content, or campaign ideas to test in the next 30 days.\n\nRemember that Google Trends shows relative interest (0 to 100), not the number of searches."}},{"id":"market-006","area":"market","es":{"t":"Reputación y noticias de mi negocio","d":"Busca noticias recientes sobre tu negocio o tu marca y te avisa si hay algo que pueda afectar tu reputación.","p":"Quiero revisar qué se publica sobre mi negocio en las noticias.\n\nNegocio o marca: [nombre exacto].\nPaís: [por ejemplo: Estados Unidos / Perú / Chile].\nPeriodo: [última semana / último mes / último año].\nIdioma de la respuesta: [español / inglés].\n\nSi te falta el país, el periodo o el idioma, pregúntamelos antes de buscar. Busca noticias recientes sobre mi negocio y, si no hay, sobre mi rubro en mi ciudad. Si además puedes leer las reseñas de mi negocio, inclúyelas. Dame: las noticias más importantes con fecha, medio y enlace; si el tono es positivo, neutral o negativo; los riesgos que veas y una respuesta sugerida si hay algo delicado.\n\nSi no encuentras menciones, dímelo claramente."},"en":{"t":"My business's reputation and news","d":"Finds recent news about your business or brand and flags anything that could affect your reputation.","p":"I want to check what the news is saying about my business.\n\nBusiness or brand: [exact name].\nCountry: [for example: United States / Peru / Chile].\nTime range: [past week / past month / past year].\nLanguage for the answer: [English / Spanish].\n\nIf the country, the time range, or the language is missing, ask me before searching. Search for recent news about my business and, if there isn't any, about my industry in my city. If you can also read my business's reviews, include them. Give me: the most important stories with date, outlet, and link; whether the tone is positive, neutral, or negative; any risks you see; and a suggested response if something is sensitive.\n\nIf you don't find any mentions, tell me clearly."}},{"id":"market-007","area":"market","es":{"t":"Qué dicen Google y la IA de TerminalSync sobre mi negocio","d":"Revisa cómo apareces en Google y qué respuesta con IA obtiene TerminalSync cuando alguien pregunta por tu negocio o tu rubro.","p":"Quiero saber cómo aparece mi negocio cuando alguien lo busca en Google y qué respuesta con IA obtiene TerminalSync.\n\nNegocio: [nombre].\nSitio web: [dirección, si tienes].\nCiudad y país: [por ejemplo: Orlando, Florida, EE. UU. / Guadalajara, México].\nPreguntas que haría un cliente: [de 1 a 3 — por ejemplo: \"mejor dentista en Orlando\", \"dónde comprar café de especialidad en Guadalajara\"].\nIdioma de la respuesta: [español / inglés].\n\nSi te falta la ciudad, el país o el idioma, pregúntamelos antes de buscar. Busca esas preguntas en Google y revisa la respuesta con IA que TerminalSync obtiene para cada una. Dame: en qué posición aparezco en Google (o si no aparezco), qué competidores salen antes, qué respuesta con IA sobre mi negocio aparece y si me menciona, y cinco acciones concretas para mejorar mi visibilidad.\n\nNo supongas posiciones ni respuestas que no hayas visto."},"en":{"t":"What Google and TerminalSync’s AI say about my business","d":"See how your business appears on Google and what AI-powered answer TerminalSync retrieves when people ask about your business or industry.","p":"I want to know how my business appears on Google and what AI-powered answer TerminalSync retrieves.\n\nBusiness: [name].\nWebsite: [address, if you have one].\nCity and country: [for example: Orlando, Florida, USA / Guadalajara, Mexico].\nQuestions a customer would ask: [1 to 3 — for example: \"best dentist in Orlando\", \"where to buy specialty coffee in Guadalajara\"].\nLanguage for the answer: [English / Spanish].\n\nIf the city, the country, or the language is missing, ask me before searching. Search those questions on Google and review the AI-powered answer TerminalSync retrieves for each one. Tell me: where I appear on Google (or whether I do not appear), which competitors appear ahead, what the AI-powered answer says about my business and whether it mentions me, plus five concrete actions to improve my visibility.\n\nDo not assume positions or answers you have not seen."}},{"id":"market-008","area":"market","es":{"t":"Precios en Amazon, Walmart y eBay","d":"Busca productos como el tuyo en Amazon, Walmart o eBay y te arma una tabla con precios, calificaciones y vendedores para comparar.","p":"Quiero comparar el precio de mi producto con lo que se vende en Amazon, Walmart o eBay.\n\nProducto: [tipo, marca, tamaño o modelo].\nMi precio actual: [monto y moneda].\nTiendas: [Amazon / Walmart / eBay / las tres].\nPaís: [por ejemplo: Estados Unidos / México].\nIdioma de la respuesta: [español / inglés].\n\nSi te falta el país, la tienda o el idioma, pregúntamelos antes de buscar. Cada tienda vende solo en algunos países: si una no está disponible en mi país, dímelo en vez de buscar ahí. Busca productos comparables en cada tienda y arma una tabla con: producto, tienda, precio tal como aparece, calificación, número de reseñas, vendedor y si es nuevo o usado cuando se indique. Después dame el rango de precios de cada tienda, dónde queda mi precio y una recomendación.\n\nAclara siempre de qué tienda y de qué país es cada precio. Usa solo los precios que encuentres; no los estimes."},"en":{"t":"Prices on Amazon, Walmart, and eBay","d":"Searches Amazon, Walmart, or eBay for products like yours and builds a table with prices, ratings, and sellers to compare.","p":"I want to compare my product's price with what's sold on Amazon, Walmart, or eBay.\n\nProduct: [type, brand, size, or model].\nMy current price: [amount and currency].\nStores: [Amazon / Walmart / eBay / all three].\nCountry: [for example: United States / Mexico].\nLanguage for the answer: [English / Spanish].\n\nIf the country, the store, or the language is missing, ask me before searching. Each store only sells in some countries: if one isn't available in my country, tell me instead of searching there. Look for comparable products in each store and build a table with: product, store, price as shown, rating, number of reviews, seller, and whether it's new or used when stated. Then give me each store's price range, where my price falls, and a recommendation.\n\nAlways say which store and which country each price comes from. Use only the prices you find; don't estimate them."}},{"id":"market-009","area":"market","es":{"t":"Qué está contratando mi competencia","d":"Busca las ofertas de empleo publicadas por tus competidores o por tu rubro y te dice qué puestos buscan, qué salarios ofrecen cuando los publican y qué puede indicar eso de sus planes.","p":"Quiero saber qué puestos está contratando mi competencia.\n\nEmpresas o rubro: [de 1 a 3 competidores por su nombre, o el rubro — por ejemplo: clínicas dentales, restaurantes, agencias de marketing].\nCiudad y país: [por ejemplo: Houston, Texas, EE. UU. / Ciudad de México, México].\nIdioma de la respuesta: [español / inglés].\n\nSi te falta la ciudad, el país o el idioma, pregúntamelos antes de buscar. Busca las ofertas de empleo publicadas y arma una tabla con: puesto, empresa, ciudad, tipo de contrato, salario si lo publican, fecha de publicación, dónde se publicó y enlace. Después dime: qué puestos se repiten, qué rangos de salario aparecen, qué habilidades piden y qué podrían indicar esas contrataciones sobre los planes de mis competidores (abrir una sede, vender más, lanzar un servicio). Termina con ideas para mi propio equipo.\n\nSi una oferta no dice el salario, no lo estimes. Presenta lo de los planes como posibilidades, no como hechos."},"en":{"t":"What my competitors are hiring for","d":"Searches the job postings from your competitors or your industry and tells you which roles they're hiring for, what salaries they offer when they post them, and what that could say about their plans.","p":"I want to know which roles my competitors are hiring for.\n\nCompanies or industry: [1 to 3 competitors by name, or the industry — for example: dental clinics, restaurants, marketing agencies].\nCity and country: [for example: Houston, Texas, USA / Mexico City, Mexico].\nLanguage for the answer: [English / Spanish].\n\nIf the city, the country, or the language is missing, ask me before searching. Search the published job postings and build a table with: role, company, city, type of contract, salary if posted, posting date, where it was posted, and link. Then tell me: which roles repeat, which salary ranges show up, which skills they ask for, and what those hires could suggest about my competitors' plans (opening a new location, selling more, launching a service). Finish with ideas for my own team.\n\nIf a posting doesn't show the salary, don't estimate it. Present the part about their plans as possibilities, not facts."}},{"id":"social-001","area":"social","es":{"t":"Qué publica mi competencia en redes","d":"Revisa los perfiles públicos de Instagram o Facebook de negocios, marcas o creadores de tu rubro y te resume qué publican, cada cuánto y qué les funciona.","p":"Quiero ver qué publican en redes los negocios y las marcas con los que compito.\n\nPerfiles a revisar: [de 1 a 3 cuentas de negocios, marcas o creadores — el usuario (@ejemplo) o el enlace del perfil de Instagram o de la página de Facebook].\nMi negocio: [qué vendes o qué servicio das].\nCiudad y país de mi mercado: [por ejemplo: Miami, Florida, EE. UU. / Medellín, Colombia].\nIdioma de la respuesta: [español / inglés].\n\nSi te falta algún perfil, el país o el idioma, pregúntamelos antes de buscar. Revisa solo perfiles públicos de negocios, marcas o creadores: si una cuenta es de una persona privada, no la busques y dímelo. De cada perfil, mira sus publicaciones más recientes y dame: cuántos seguidores tiene, cada cuánto publica, qué temas y formatos repite, qué publicaciones tienen más likes y comentarios, y qué tono usa. Termina con cinco ideas de publicaciones para mi negocio inspiradas en lo que les funciona, sin copiarlas.\n\nUsa solo los números que aparezcan en los perfiles; si no ves un dato, dímelo."},"en":{"t":"What my competitors post on social media","d":"Reviews the public Instagram or Facebook profiles of businesses, brands, or creators in your field and sums up what they post, how often, and what works for them.","p":"I want to see what the businesses and brands I compete with post on social media.\n\nProfiles to review: [1 to 3 accounts of businesses, brands, or creators — the username (@example) or the link to the Instagram profile or Facebook page].\nMy business: [what you sell or what service you offer].\nCity and country of my market: [for example: Miami, Florida, USA / Medellín, Colombia].\nLanguage for the answer: [English / Spanish].\n\nIf a profile, the country, or the language is missing, ask me before searching. Only review public profiles of businesses, brands, or creators: if an account belongs to a private person, don't look it up and tell me. For each profile, look at its most recent posts and give me: how many followers it has, how often it posts, which topics and formats it repeats, which posts get the most likes and comments, and what tone it uses. Finish with five post ideas for my business inspired by what works for them, without copying them.\n\nUse only the numbers that appear on the profiles; if you can't see something, tell me."}},{"id":"social-002","area":"social","es":{"t":"Qué videos funcionan en mi nicho","d":"Busca en YouTube o TikTok los videos de tu tema y te muestra cuáles tienen más vistas y qué formatos, títulos y temas se repiten.","p":"Quiero saber qué videos funcionan en mi nicho para inspirar mi contenido.\n\nTema o nicho: [por ejemplo: recetas saludables, rutinas de pilates, remodelación de cocinas].\nPlataforma: [YouTube / TikTok / las dos].\nPaís: [por ejemplo: Estados Unidos / México / Colombia].\nIdioma de los videos: [español / inglés].\nIdioma de la respuesta: [español / inglés].\n\nSi te falta el país o el idioma, pregúntamelos antes de buscar. Busca videos de mi tema en la plataforma que elegí (si elijo las dos, busca en cada una; si una no está disponible, dímelo) y arma una tabla con: título, canal o cuenta, vistas, likes, fecha de publicación, duración y enlace. Después dime: qué formatos se repiten entre los más vistos (tutorial, antes y después, lista, reacción…), qué prometen los títulos, cuánto duran y qué temas tienen más vistas. Termina con cinco ideas de videos para mi negocio.\n\nUsa solo los números que aparezcan en los resultados; si un video no muestra vistas o fecha, déjalo en blanco en vez de estimarlo."},"en":{"t":"Which videos work in my niche","d":"Searches YouTube or TikTok for videos on your topic and shows you which ones get the most views and which formats, titles, and topics repeat.","p":"I want to know which videos work in my niche to inspire my content.\n\nTopic or niche: [for example: healthy recipes, pilates routines, kitchen remodeling].\nPlatform: [YouTube / TikTok / both].\nCountry: [for example: United States / Mexico / Colombia].\nLanguage of the videos: [English / Spanish].\nLanguage for the answer: [English / Spanish].\n\nIf the country or the language is missing, ask me before searching. Search for videos on my topic on the platform I chose (if I choose both, search each one; if one isn't available, tell me) and build a table with: title, channel or account, views, likes, publish date, length, and link. Then tell me: which formats repeat among the most-watched (tutorial, before and after, list, reaction…), what the titles promise, how long they run, and which topics get the most views. Finish with five video ideas for my business.\n\nUse only the numbers that appear in the results; if a video doesn't show views or a date, leave it blank instead of estimating it."}},{"id":"travel-001","area":"travel","es":{"t":"Mi reputación en Tripadvisor","d":"Revisa cómo aparece tu hotel, restaurante o tour en Tripadvisor, cómo te comparas con los de tu zona y, si se pueden leer, qué dicen tus reseñas.","p":"Quiero saber cómo está mi reputación en Tripadvisor.\n\nMi negocio: [nombre exacto, como aparece en Tripadvisor].\nTipo: [hotel / restaurante / tour o actividad / otro].\nCiudad y país: [por ejemplo: Orlando, Florida, EE. UU. / Cartagena, Colombia].\nIdioma de la respuesta: [español / inglés].\n\nSi te falta la ciudad, el país o el idioma, pregúntamelos antes de buscar. Busca mi negocio en Tripadvisor y dame su calificación, número de opiniones, ranking en la ciudad y rango de precio, si aparecen. Busca también los negocios de mi tipo mejor calificados en la zona y arma una tabla para compararme. Si además puedes leer las reseñas de Tripadvisor, resume qué elogian y de qué se quejan mis clientes y sugiéreme una respuesta para la reseña negativa más reciente. Termina con cinco acciones para mejorar mi reputación.\n\nSi no encuentras mi negocio o un dato no aparece en Tripadvisor, dímelo en vez de suponerlo."},"en":{"t":"My Tripadvisor reputation","d":"Reviews how your hotel, restaurant, or tour shows up on Tripadvisor, how you compare with others in your area, and, if they can be read, what your reviews say.","p":"I want to know how my reputation looks on Tripadvisor.\n\nMy business: [exact name, as it appears on Tripadvisor].\nType: [hotel / restaurant / tour or activity / other].\nCity and country: [for example: Orlando, Florida, USA / Cartagena, Colombia].\nLanguage for the answer: [English / Spanish].\n\nIf the city, the country, or the language is missing, ask me before searching. Look up my business on Tripadvisor and give me its rating, number of reviews, ranking in the city, and price range, if they appear. Also look up the best-rated businesses of my type in the area and build a table to compare me with them. If you can also read the Tripadvisor reviews, sum up what my customers praise and complain about and suggest a reply to the most recent negative review. Finish with five actions to improve my reputation.\n\nIf you can't find my business or something doesn't appear on Tripadvisor, tell me instead of guessing."}},{"id":"travel-002","area":"travel","es":{"t":"Precio de mi Airbnb contra la zona","d":"Busca en Airbnb alojamientos parecidos al tuyo en tu zona y para tus fechas, y te dice si tu precio por noche está alto, bajo o en el promedio.","p":"Quiero saber si el precio de mi alojamiento en Airbnb está bien comparado con la zona.\n\nZona: [barrio o ciudad, y país — por ejemplo: Brickell, Miami, EE. UU. / El Poblado, Medellín, Colombia].\nFechas: [llegada y salida, por ejemplo: del 12 al 15 de diciembre; o, si no tienes fechas: un fin de semana, una semana o un mes].\nMi alojamiento: [entero o habitación, número de habitaciones y para cuántos huéspedes].\nMi precio por noche: [monto y moneda].\nIdioma de la respuesta: [español / inglés].\n\nSi te falta la zona, las fechas o el idioma, pregúntamelos antes de buscar. Busca en Airbnb alojamientos parecidos al mío en esa zona y para esas fechas, y arma una tabla con: título, tipo de lugar, habitaciones, precio por noche, precio total, calificación, número de reseñas, si el anfitrión es Superanfitrión y enlace. Después dame el rango de precios (bajo, medio y alto), dónde queda mi precio y una recomendación.\n\nAclara siempre para qué fechas son los precios: en Airbnb cambian según las fechas y la cantidad de noches. Usa solo los precios que encuentres; no los estimes."},"en":{"t":"My Airbnb price vs. the area","d":"Searches Airbnb for stays like yours in your area and for your dates, and tells you whether your nightly price is high, low, or about average.","p":"I want to know whether my Airbnb's price is right compared with the area.\n\nArea: [neighborhood or city, and country — for example: Brickell, Miami, USA / El Poblado, Medellín, Colombia].\nDates: [check-in and check-out, for example: December 12 to 15; or, if you don't have dates: a weekend, a week, or a month].\nMy place: [entire place or room, number of bedrooms, and how many guests].\nMy nightly price: [amount and currency].\nLanguage for the answer: [English / Spanish].\n\nIf the area, the dates, or the language is missing, ask me before searching. Search Airbnb for places like mine in that area and for those dates, and build a table with: title, type of place, bedrooms, nightly price, total price, rating, number of reviews, whether the host is a Superhost, and link. Then give me the price range (low, mid, and high), where my price falls, and a recommendation.\n\nAlways say which dates the prices are for: on Airbnb they change with the dates and the number of nights. Use only the prices you find; don't estimate them."}},{"id":"travel-003","area":"travel","es":{"t":"Qué tan llena está mi zona en Airbnb","d":"Revisa el calendario de alojamientos de Airbnb de tu zona y te dice qué parte de los días aparece no disponible, aclarando que eso incluye reservas y bloqueos del anfitrión.","p":"Quiero tener una idea de qué tan llena está mi zona en Airbnb.\n\nZona: [barrio o ciudad, y país — por ejemplo: Kissimmee, Florida, EE. UU. / Tulum, México].\nTipo de alojamiento: [entero o habitación, y número de habitaciones].\nDesde qué fecha mirar: [por ejemplo: 1 de noviembre].\nCuántos meses: [1, 2 o 3].\nIdioma de la respuesta: [español / inglés].\n\nSi te falta la zona, la fecha o el idioma, pregúntamelos antes de buscar. Busca en Airbnb alojamientos parecidos en esa zona y revisa el calendario de hasta 4 de ellos para el periodo que elegí. Dame una tabla con: alojamiento, precio por noche, días revisados, días no disponibles, porcentaje no disponible y enlace. Después dame el promedio de esos alojamientos, qué semanas aparecen más llenas y qué significa para mi precio.\n\nImportante: en Airbnb un día \"no disponible\" puede estar reservado o bloqueado por el anfitrión, y no se puede saber cuál de los dos. No lo llames ocupación sin aclararlo, y dime con cuántos alojamientos calculaste el promedio."},"en":{"t":"How booked up my area is on Airbnb","d":"Checks the calendar of Airbnb stays in your area and tells you what share of the days shows as unavailable, making clear that this includes bookings and dates blocked by the host.","p":"I want to get an idea of how booked up my area is on Airbnb.\n\nArea: [neighborhood or city, and country — for example: Kissimmee, Florida, USA / Tulum, Mexico].\nType of place: [entire place or room, and number of bedrooms].\nStart date to check: [for example: November 1].\nHow many months: [1, 2, or 3].\nLanguage for the answer: [English / Spanish].\n\nIf the area, the date, or the language is missing, ask me before searching. Search Airbnb for similar places in that area and check the calendar of up to 4 of them for the period I chose. Give me a table with: place, nightly price, days checked, unavailable days, percentage unavailable, and link. Then give me the average across those places, which weeks look the most booked, and what it means for my price.\n\nImportant: on Airbnb an \"unavailable\" day can be booked or blocked by the host, and there's no way to tell which. Don't call it occupancy without saying so, and tell me how many places you used for the average."}},{"id":"travel-004","area":"travel","es":{"t":"Qué dicen los huéspedes de mi competencia","d":"Encuentra los alojamientos de Airbnb mejor calificados de tu zona, lee sus reseñas y te dice qué valoran los huéspedes y de qué se quejan.","p":"Quiero saber qué valoran y qué critican los huéspedes de los alojamientos de Airbnb que compiten con el mío.\n\nZona: [barrio o ciudad, y país — por ejemplo: Miami Beach, Florida, EE. UU. / Getsemaní, Cartagena, Colombia].\nTipo de alojamiento: [entero o habitación, y número de habitaciones].\nIdioma de la respuesta: [español / inglés].\n\nSi te falta la zona o el idioma, pregúntamelos antes de buscar. Busca en Airbnb los alojamientos parecidos al mío mejor calificados en esa zona (si buscas sin fechas, dime qué fechas usó la búsqueda) y lee las reseñas más recientes de hasta 3 de ellos. Dame: una tabla con alojamiento, calificación, número de reseñas y enlace; lo que más elogian los huéspedes (limpieza, ubicación, comunicación, camas, vista…); de qué se quejan; cómo responden los anfitriones; y cinco mejoras concretas para mi alojamiento y mi anuncio.\n\nCita frases cortas de las reseñas sin los nombres de los huéspedes. Si un alojamiento no tiene reseñas, dímelo."},"en":{"t":"What my competitors' guests say","d":"Finds the best-rated Airbnb stays in your area, reads their reviews, and tells you what guests value and what they complain about.","p":"I want to know what guests value and criticize about the Airbnb places that compete with mine.\n\nArea: [neighborhood or city, and country — for example: Miami Beach, Florida, USA / Getsemaní, Cartagena, Colombia].\nType of place: [entire place or room, and number of bedrooms].\nLanguage for the answer: [English / Spanish].\n\nIf the area or the language is missing, ask me before searching. Search Airbnb for the best-rated places like mine in that area (if you search without dates, tell me which dates the search used) and read the most recent reviews of up to 3 of them. Give me: a table with place, rating, number of reviews, and link; what guests praise most (cleanliness, location, communication, beds, view…); what they complain about; how hosts reply; and five concrete improvements for my place and my listing.\n\nQuote short phrases from the reviews without the guests' names. If a place has no reviews, tell me."}},{"id":"cont-001","area":"continuity","es":{"t":"Continuar trabajo iniciado en WhatsApp","d":"Retoma sin perder hilo lo que empezaste a discutir por WhatsApp.","p":"Estuve hablando con alguien por WhatsApp sobre un tema y necesito retomarlo aquí con contexto completo.\n\nCon quién hablé: [persona/cliente/proveedor].\nTema de la conversación: [describir].\nResumen de lo que se dijo: [pegar mensajes clave o resumir].\nLo que quedó pendiente: [próximo paso].\n\nAyúdame a: ordenar lo conversado, identificar decisiones tomadas, listar pendientes con responsable y armar el siguiente mensaje o documento que tengo que producir."},"en":{"t":"Continue work started on WhatsApp","d":"Pick up what you started discussing on WhatsApp without losing the thread.","p":"I was talking with someone on WhatsApp about a topic and need to resume it here with full context.\n\nWho I spoke with: [person/client/supplier].\nTopic of the conversation: [describe].\nSummary of what was said: [paste key messages or summarize].\nWhat was left pending: [next step].\n\nHelp me to: organize what was discussed, identify decisions made, list pending items with owners, and draft the next message or document I need to produce."}},{"id":"cont-002","area":"continuity","es":{"t":"Continuar trabajo iniciado en Telegram","d":"Convierte un hilo de Telegram en trabajo accionable.","p":"Vengo de una conversación en Telegram y quiero retomarla aquí con orden.\n\nGrupo o chat: [describir contexto].\nTema central: [describir].\nMensajes clave: [pegar o resumir].\nLo que quedó por hacer: [listar].\n\nAyúdame a: extraer las decisiones del hilo, separar lo importante del ruido, listar pendientes con dueño y plazo, y proponer el siguiente paso concreto."},"en":{"t":"Continue work started on Telegram","d":"Turn a Telegram thread into actionable work.","p":"I'm coming from a conversation on Telegram and want to pick it up here in an organized way.\n\nGroup or chat: [describe context].\nCentral topic: [describe].\nKey messages: [paste or summarize].\nWhat remains to be done: [list].\n\nHelp me to: extract the decisions from the thread, separate what's important from the noise, list pending items with owner and deadline, and propose the concrete next step."}},{"id":"cont-003","area":"continuity","es":{"t":"Continuar investigación desde Chrome","d":"Consolida lo que investigaste en el navegador en un solo documento útil.","p":"Estuve investigando un tema en Chrome y tengo varias pestañas, links y notas sueltas. Quiero consolidarlo.\n\nTema de la investigación: [describir].\nLinks/fuentes principales: [pegar URLs o títulos].\nLo que ya saqué en limpio: [resumir si tienes].\nObjetivo final: [decisión / informe / propuesta].\n\nAyúdame a: organizar la información por subtemas, identificar lo más importante, completar lo que falta y armar un documento final claro listo para compartir."},"en":{"t":"Continue research from Chrome","d":"Consolidate what you researched in the browser into a single useful document.","p":"I was researching a topic in Chrome and have several tabs, links and loose notes. I want to consolidate it.\n\nResearch topic: [describe].\nMain links/sources: [paste URLs or titles].\nWhat I've already distilled: [summarize if you have].\nFinal objective: [decision / report / proposal].\n\nHelp me to: organize the information by subtopics, identify the most important points, fill in what's missing, and prepare a clear final document ready to share."}},{"id":"cont-004","area":"continuity","es":{"t":"Convertir conversación en tareas","d":"Tu conversación se transforma en una lista de tareas con responsables y fechas.","p":"Tuve una conversación que terminó con varias cosas por hacer pero todo quedó suelto. Quiero convertirla en tareas claras.\n\nContexto de la conversación: [reunión / chat / llamada].\nParticipantes: [listar].\nResumen o transcripción: [pegar].\n\nDame: lista de tareas accionables, responsable sugerido de cada una, fecha límite tentativa, prioridad (alta/media/baja) y el mensaje para confirmarlas con el equipo."},"en":{"t":"Turn conversation into tasks","d":"Your conversation is transformed into a list of tasks with owners and dates.","p":"I had a conversation that ended with several things to do but everything is loose. I want to convert it into clear tasks.\n\nConversation context: [meeting / chat / call].\nParticipants: [list].\nSummary or transcript: [paste].\n\nGive me: a list of actionable tasks, a suggested owner for each, a tentative due date, priority (high/medium/low), and the message to confirm them with the team."}},{"id":"cont-005","area":"continuity","es":{"t":"Convertir chat en documentación","d":"Una conversación se vuelve un documento que cualquiera entiende sin contexto.","p":"Tengo una conversación importante donde se decidieron cosas pero no queda nada documentado. Quiero convertirla en un documento útil.\n\nTema: [describir].\nParticipantes: [listar].\nConversación: [pegar o resumir].\n\nAyúdame a producir un documento con: contexto y antecedentes, decisiones tomadas con justificación, acuerdos operativos, qué quedó pendiente para futura definición y formato listo para guardar o compartir."},"en":{"t":"Turn chat into documentation","d":"A conversation becomes a document that anyone can understand without prior context.","p":"I have an important conversation where decisions were made but nothing is documented. I want to turn it into a useful document.\n\nTopic: [describe].\nParticipants: [list].\nConversation: [paste or summarize].\n\nHelp me produce a document with: context and background, decisions made with justification, operational agreements, what was left pending for future definition, and a format ready to save or share."}},{"id":"cont-006","area":"continuity","es":{"t":"Recuperar contexto de un proyecto","d":"Te pones al día rápido en un proyecto que dejaste pausado o que retomas con poca info.","p":"Voy a retomar un proyecto en el que no estuve hace un tiempo (o que recién recibo) y necesito ponerme al día rápido.\n\nProyecto: [describir].\nMi rol: [describir].\nLo que sé hasta ahora: [resumir].\nQué necesito decidir o hacer en los próximos días: [listar].\n\nAyúdame a: identificar la información clave que me falta, qué preguntas hacer a quién, riesgos visibles del proyecto y un plan de acción para mis primeros 7 días."},"en":{"t":"Recover project context","d":"Get up to speed quickly on a project you paused or are taking over with little information.","p":"I'm going to resume a project I haven't been involved with for a while (or that I just received) and need to get up to speed quickly.\n\nProject: [describe].\nMy role: [describe].\nWhat I know so far: [summarize].\nWhat I need to decide or do in the next few days: [list].\n\nHelp me: identify the key missing information, what questions to ask whom, visible project risks, and an action plan for my first 7 days."}},{"id":"cont-007","area":"continuity","es":{"t":"Continuar desde móvil","d":"Lo que empezaste en el celular sigue acá sin perder el hilo.","p":"Empecé algo en el celular (nota, mensaje, idea suelta) y lo quiero terminar aquí con calma y mejor herramienta.\n\nLo que empecé: [pegar texto o describir].\nObjetivo final: [email / documento / propuesta / publicación].\nA quién va dirigido: [destinatario].\n\nAyúdame a: ordenar lo que escribí, completarlo profesionalmente, ajustar el tono al destinatario y dejarlo listo para enviar."},"en":{"t":"Continue from mobile","d":"What you started on your phone carries over here without losing the thread.","p":"I started something on my phone (note, message, loose idea) and want to finish it here with a calmer, better tool.\n\nWhat I started: [paste the text or describe].\nFinal objective: [email / document / proposal / publication].\nWho it's for: [recipient].\n\nHelp me to: organize what I wrote, complete it professionally, adjust the tone for the recipient, and leave it ready to send."}},{"id":"cont-008","area":"continuity","es":{"t":"Continuar desde escritorio","d":"Algo que dejaste a medias en otra máquina sigue acá sin reempezar.","p":"Estuve trabajando en otra computadora y dejé algo a medias. Quiero continuar acá sin perder lo avanzado.\n\nQué estaba haciendo: [describir].\nDónde quedé: [punto exacto].\nMaterial que ya tengo: [archivos / notas].\nObjetivo final: [resultado].\n\nAyúdame a: revisar lo hecho, identificar lo que falta, sugerir el siguiente paso concreto y terminarlo con orden."},"en":{"t":"Continue from desktop","d":"Something you left halfway on another machine continues here without restarting.","p":"I was working on another computer and left something half done. I want to continue here without losing what I've already done.\n\nWhat I was doing: [describe].\nWhere I left off: [exact point].\nMaterial I already have: [files / notes].\nFinal objective: [result].\n\nHelp me to: review what's been done, identify what's missing, suggest the concrete next step, and finish it in an organized way."}},{"id":"cont-009","area":"continuity","es":{"t":"Preparar respuesta rápida desde WhatsApp","d":"Una respuesta lista para copiar y mandar en WhatsApp sin sonar improvisado.","p":"Tengo que responder un mensaje importante por WhatsApp y quiero hacerlo bien pero rápido.\n\nMensaje que recibí: [pegar].\nContexto de la relación: [cliente / proveedor / equipo / personal].\nObjetivo de mi respuesta: [aclarar / cerrar / posponer / ofrecer].\nTono que quiero: [profesional / cálido / firme].\n\nDame: 2 opciones de respuesta cortas, listas para copiar a WhatsApp, con el tono indicado y un cierre claro que invite a continuar la conversación."},"en":{"t":"Prepare a quick reply from WhatsApp","d":"A reply ready to copy and send on WhatsApp without sounding improvised.","p":"I need to reply to an important message on WhatsApp and I want to do it well but fast.\n\nMessage I received: [paste].\nRelationship context: [client / supplier / team / staff].\nGoal of my reply: [clarify / close / postpone / offer].\nTone I want: [professional / warm / firm].\n\nGive me: 2 short response options, ready to copy to WhatsApp, with the indicated tone and a clear closing that invites continuing the conversation."}},{"id":"cont-010","area":"continuity","es":{"t":"Compartir contexto con equipo","d":"Un resumen que pone a tu equipo al día sin tener que reexplicar todo.","p":"Necesito poner al día a mi equipo sobre algo en lo que vengo trabajando solo. Quiero un mensaje claro.\n\nTema: [describir].\nLo que ya hice: [listar].\nLo que sigue: [próximos pasos].\nA quién se lo voy a mandar: [equipo / socio / responsable].\n\nDame: mensaje principal (corto), bullets con lo más importante, qué necesito de cada persona y cómo van a quedar las próximas decisiones. Formato listo para Slack, email o WhatsApp grupal."},"en":{"t":"Share context with team","d":"A summary that brings your team up to date without having to re-explain everything.","p":"I need to bring my team up to speed on something I've been working on alone. I want a clear message.\n\nTopic: [describe].\nWhat I've already done: [list].\nWhat comes next: [next steps].\nWho I'm sending this to: [team / partner / lead].\n\nGive me: main message (short), bullets with the most important points, what I need from each person and how the next decisions will be handled. Format ready for Slack, email or group WhatsApp."}}],"jobCategories":[{"id":"ventas","es":"Ventas","en":"Sales"},{"id":"marketing","es":"Marketing","en":"Marketing"},{"id":"operaciones","es":"Operaciones","en":"Operations"},{"id":"legal","es":"Legal","en":"Legal"},{"id":"alojamientos","es":"Alojamientos","en":"Rentals"},{"id":"software","es":"Software","en":"Software"}],"jobs":[{"id":"buscar-clientes","cat":"ventas","es":{"t":"Buscador de clientes potenciales","d":"Investiga tu mercado y te entrega una lista de prospectos calificados.","cad":"Cada lunes","rep":"Lista con contactos y por qué encajan, en tu carpeta de Ventas","steps":["Investiga empresas que encajan con tu cliente ideal","Filtra y califica según tus criterios","Prepara el primer mensaje sugerido para cada uno"]},"en":{"t":"Prospect finder","d":"Researches your market and delivers a list of qualified prospects.","cad":"Every Monday","rep":"A list with contacts and why they fit, in your Sales folder","steps":["Researches companies matching your ideal client","Filters and qualifies by your criteria","Drafts a suggested first message for each"]}},{"id":"propuestas-auto","cat":"ventas","es":{"t":"Preparador de propuestas","d":"Convierte los datos de un cliente en una propuesta lista para revisar.","cad":"Cuando se lo pidas","rep":"Propuesta en tu formato, avisa por WhatsApp al terminar","steps":["Lee la carpeta del cliente y el histórico","Arma la propuesta con tu plantilla y precios","Te la deja lista para revisar y enviar"]},"en":{"t":"Proposal builder","d":"Turns a client’s details into a proposal ready to review.","cad":"On demand","rep":"Proposal in your format, pings you on WhatsApp when done","steps":["Reads the client folder and history","Builds the proposal with your template and pricing","Leaves it ready to review and send"]}},{"id":"crm-aldia","cat":"ventas","es":{"t":"CRM siempre al día","d":"Registra cada interacción y te avisa qué seguimiento toca hoy.","cad":"Todos los días, 7:00 am","rep":"Resumen diario: qué se movió y a quién contactar","steps":["Revisa correos y conversaciones nuevas","Actualiza el estado de cada negocio","Prepara la lista de seguimientos del día"]},"en":{"t":"CRM always up to date","d":"Logs every interaction and tells you which follow-up is due today.","cad":"Daily, 7:00 am","rep":"Daily digest: what moved and who to contact","steps":["Reviews new emails and conversations","Updates each deal’s status","Prepares today’s follow-up list"]}},{"id":"seo-mensual","cat":"marketing","es":{"t":"Analista SEO mensual","d":"Revisa tu sitio y el de tus competidores y te dice dónde ganar.","cad":"El 1° de cada mes","rep":"Informe con hallazgos y 5 acciones priorizadas","steps":["Analiza posiciones, contenido y competidores","Detecta oportunidades y caídas","Prioriza qué publicar o corregir este mes"]},"en":{"t":"Monthly SEO analyst","d":"Reviews your site and competitors and tells you where to win.","cad":"1st of every month","rep":"Report with findings and 5 prioritized actions","steps":["Analyzes rankings, content and competitors","Spots opportunities and drops","Prioritizes what to publish or fix this month"]}},{"id":"contenido-semanal","cat":"marketing","es":{"t":"Productor de contenido","d":"Produce los borradores de la semana en tu voz, listos para aprobar.","cad":"Cada viernes","rep":"Piezas en tu carpeta de Marketing + aviso por Telegram","steps":["Lee tu calendario y temas del mes","Escribe posts, correos y guiones en tu tono","Deja todo en borradores para tu revisión"]},"en":{"t":"Content producer","d":"Produces the week’s drafts in your voice, ready to approve.","cad":"Every Friday","rep":"Pieces in your Marketing folder + Telegram ping","steps":["Reads your calendar and monthly topics","Writes posts, emails and scripts in your tone","Leaves everything as drafts for review"]}},{"id":"vigia-campanas","cat":"marketing","es":{"t":"Vigía de campañas","d":"Monitorea tus anuncios y te alerta antes de quemar presupuesto.","cad":"Todos los días","rep":"Alerta solo si algo se sale de rango; resumen semanal","steps":["Revisa métricas de cada campaña activa","Compara contra tus metas y costos máximos","Sugiere pausar, escalar o ajustar"]},"en":{"t":"Campaign watchdog","d":"Monitors your ads and alerts you before budget burns.","cad":"Daily","rep":"Alerts only if something drifts; weekly summary","steps":["Checks metrics on every active campaign","Compares against your targets and max costs","Suggests pausing, scaling or adjusting"]}},{"id":"reporte-lunes","cat":"operaciones","es":{"t":"Reportero de los lunes","d":"Arma el informe semanal del negocio sin que nadie lo persiga.","cad":"Cada lunes, 6:00 am","rep":"Informe en PDF + correo al equipo","steps":["Junta los datos de tus fuentes","Arma el informe con tu formato","Lo envía al equipo y te avisa"]},"en":{"t":"Monday reporter","d":"Builds the weekly business report without anyone chasing it.","cad":"Every Monday, 6:00 am","rep":"PDF report + email to the team","steps":["Gathers data from your sources","Builds the report in your format","Sends it to the team and pings you"]}},{"id":"clasificador","cat":"operaciones","es":{"t":"Clasificador de correos y documentos","d":"Ordena lo que llega: facturas, contratos, soporte, spam.","cad":"Cada hora","rep":"Todo archivado en su carpeta; urgentes a tu WhatsApp","steps":["Lee lo nuevo en el correo y las carpetas","Clasifica y archiva según tus reglas","Escala solo lo que necesita tu decisión"]},"en":{"t":"Email & document sorter","d":"Sorts what comes in: invoices, contracts, support, spam.","cad":"Hourly","rep":"Everything filed in its folder; urgent items to your WhatsApp","steps":["Reads new mail and folder drops","Classifies and files by your rules","Escalates only what needs your decision"]}},{"id":"pendientes","cat":"operaciones","es":{"t":"Monitor de pendientes","d":"Persigue las tareas vencidas para que nada se enfríe.","cad":"Todos los días, 5:00 pm","rep":"Lista de vencidos y quién los tiene, cada tarde","steps":["Revisa tareas y compromisos de cada espacio","Detecta lo vencido o a punto de vencer","Redacta los recordatorios para enviar"]},"en":{"t":"Overdue tracker","d":"Chases overdue tasks so nothing goes cold.","cad":"Daily, 5:00 pm","rep":"List of overdue items and owners, every afternoon","steps":["Reviews tasks and commitments in each space","Flags overdue and at-risk items","Drafts the reminders to send"]}},{"id":"revisor-contratos","cat":"legal","es":{"t":"Revisor de contratos","d":"Cada contrato nuevo llega revisado, con riesgos señalados en simple.","cad":"Cuando llega un contrato","rep":"Resumen de riesgos y qué negociar, antes de tu firma","steps":["Lee el contrato que llega a la carpeta","Señala cláusulas riesgosas y las explica","Prepara la lista de puntos a negociar"]},"en":{"t":"Contract reviewer","d":"Every new contract arrives reviewed, risks flagged in plain language.","cad":"When a contract arrives","rep":"Risk summary and negotiation points, before you sign","steps":["Reads contracts dropped in the folder","Flags risky clauses and explains them","Prepares the negotiation checklist"]}},{"id":"huespedes","cat":"alojamientos","es":{"t":"Anfitrión digital","d":"Procesa cada reserva: bienvenida, portería e ingreso registrado.","cad":"Con cada reserva","rep":"Todo registrado; te avisa solo si algo requiere tu decisión","steps":["Envía la bienvenida e instrucciones al huésped","Notifica a portería con los datos del ingreso","Registra la reserva y el pago en tu control"]},"en":{"t":"Digital host","d":"Handles each booking: welcome, front desk and logged check-in.","cad":"With every booking","rep":"Everything logged; pings you only if something needs your call","steps":["Sends the guest welcome and instructions","Notifies the front desk with check-in details","Logs the booking and payment in your tracker"]}},{"id":"guardian-bugs","cat":"software","es":{"t":"Guardián del código","d":"Revisa bugs reportados, corre pruebas y propone correcciones.","cad":"Cada noche","rep":"Resumen matutino: qué se arregló y qué espera tu OK","steps":["Revisa los bugs e issues nuevos","Corre las pruebas y reproduce errores","Propone la corrección y la deja lista para revisar"]},"en":{"t":"Code guardian","d":"Reviews reported bugs, runs tests and proposes fixes.","cad":"Every night","rep":"Morning digest: what was fixed and what awaits your OK","steps":["Reviews new bugs and issues","Runs tests and reproduces errors","Proposes the fix, ready for your review"]}}]} as const;
